// This file implements the organization-scoped audit chain. Every successful
// policy publish or rollback, and every Decide called with a non-empty
// decision organization, leaves an immutable record in that organization.
//
// Records carry an organization-local sequence starting at 1 and a SHA-256
// fingerprint that chains each record to the previous one. The genesis
// fingerprint binds the organization name, so records from another
// organization can never validate as part of this chain even when the
// sequence numbers and identifiers coincide.
package darksafe

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
)

// Audit record categories.
const (
	// AuditPolicyChange is a successful publish or rollback.
	AuditPolicyChange = "policy_change"
	// AuditDecision is one Decide evaluation.
	AuditDecision = "decision"
)

// Sentinel errors for the audit entry points. Callers distinguish them
// with errors.Is; every one leaves state unchanged.
var (
	// ErrInvalidPage means a page size or range argument was invalid.
	ErrInvalidPage = errors.New("darksafe: invalid audit page")
	// ErrInvalidRange means the upper bound is beyond what exists, the
	// range is inverted, or a supplied fingerprint does not match.
	ErrInvalidRange = errors.New("darksafe: invalid audit range")
	// ErrAuditNotFound means no record exists at the requested sequence.
	ErrAuditNotFound = errors.New("darksafe: audit record not found")
	// ErrAuditNotADecision means the record at the sequence is not a
	// decision record and therefore cannot be rechecked.
	ErrAuditNotADecision = errors.New("darksafe: audit record is not a decision")
)

// PolicyChange captures a successful publish or rollback.
type PolicyChange struct {
	// Version is the newly created policy version.
	Version int
	// Policies is the full policy set of the new version.
	Policies []Policy
	// SourceVersion is the version copied by a rollback, and 0 for an
	// ordinary publish.
	SourceVersion int
	// RolledBack reports whether the change was produced by Rollback.
	RolledBack bool
}

// DecisionRecord captures one Decide call: the full request and the
// decision actually returned.
type DecisionRecord struct {
	Request  OrgRequest
	Decision Decision
}

// AuditRecord is one immutable entry in an organization's audit chain.
type AuditRecord struct {
	Org      string
	Seq      int // organization-local, starting at 1 and gapless
	Kind     string
	Change   *PolicyChange   // present when Kind == AuditPolicyChange
	Decision *DecisionRecord // present when Kind == AuditDecision

	// PrevFingerprint is the fingerprint of the preceding record, or the
	// genesis fingerprint for the first record.
	PrevFingerprint string
	// Fingerprint binds this record's full content to its predecessor.
	Fingerprint string
}

// rawEnvelopePrefix opens every raw-byte canonical encoding. It never
// coincides with the start of a JSON envelope (always '{'), so
// fingerprints from the two encodings live in collision-free spaces.
const rawEnvelopePrefix = "darksafe-audit-raw-v1\x00"

// fingerprintTag delimits one field or nested value within the canonical
// binary encoding. Distinct tags keep two payloads that merely share
// adjacent bytes apart (e.g. ["ab",""] vs ["a","b"]).
type fingerprintTag byte

const (
	tagEnvelope fingerprintTag = iota + 1
	tagSeq
	tagString
	tagStringList
	tagBool
	tagPolicy
	tagPolicyList
	tagChange
	tagSubject
	tagResource
	tagDecision
	tagDecisionRecord
)

// fingerprintEncoder builds the canonical byte representation of an
// envelope. Unlike encoding/json it writes string contents byte-for-byte
// with an explicit length prefix, so strings carrying invalid UTF-8 stay
// distinguishable: encoding/json renders both a raw 0xFF byte and a raw
// 0xFE byte as the U+FFFD replacement rune, collapsing genuinely
// different content onto identical fingerprints.
type fingerprintEncoder struct {
	buf []byte
}

func (e *fingerprintEncoder) tag(t fingerprintTag) {
	e.buf = append(e.buf, byte(t))
}

func (e *fingerprintEncoder) int64Tag(t fingerprintTag, v int64) {
	e.tag(t)
	var b [8]byte
	binary.BigEndian.PutUint64(b[:], uint64(v))
	e.buf = append(e.buf, b[:]...)
}

func (e *fingerprintEncoder) boolTag(t fingerprintTag, v bool) {
	e.tag(t)
	if v {
		e.buf = append(e.buf, 1)
	} else {
		e.buf = append(e.buf, 0)
	}
}

// rawString tags and writes a string from its exact memory bytes. No
// validation, replacement or normalization is ever performed: an invalid
// UTF-8 byte reaches the hash unchanged.
func (e *fingerprintEncoder) rawString(s string) {
	e.tag(tagString)
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(len(s)))
	e.buf = append(e.buf, b[:]...)
	e.buf = append(e.buf, s...)
}

// put appends one raw framing byte. It is the fingerprint sink's side of the
// shared list shape: the list presence marker goes into the canonical bytes
// verbatim.
func (e *fingerprintEncoder) put(b byte) {
	e.buf = append(e.buf, b)
}

// listCount writes a list element count as a big-endian uint32. The raw
// canonical encoding has no length ceiling beyond the hash input, so unlike
// the archive sink the count is written unconditionally; only the list shape
// (nil marker, presence marker, count then one item per element) is shared.
func (e *fingerprintEncoder) listCount(n int) {
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(n))
	e.buf = append(e.buf, b[:]...)
}

// stringList preserves nil-vs-empty explicitly: in the JSON envelope a
// nil slice is "null" and a non-nil empty slice is "[]", so the raw
// encoding must keep the two shapes apart as well. The list's own kind tag
// leads, then the shared list shape carries the presence marker, count and
// elements under it.
func (e *fingerprintEncoder) stringList(items []string) {
	e.tag(tagStringList)
	writeListShape(e, items, e.rawString)
}

func (e *fingerprintEncoder) policy(p Policy) {
	e.tag(tagPolicy)
	// Field order, the Recursive boolean's position, and ResourceID being
	// appended only when set all come from the single policy field table, so
	// the fingerprint and the archive enumerate fields in exactly one place.
	for i := range policyFields {
		f := &policyFields[i]
		switch f.kind {
		case policyFieldString:
			e.rawString(f.getString(p))
		case policyFieldOptionalString:
			// ResourceID participates only when set, pairing with its
			// omitempty JSON tag, so the legacy fingerprint bytes are
			// unchanged for resource-unrestricted policies.
			if v := f.getString(p); v != "" {
				e.rawString(v)
			}
		case policyFieldBool:
			e.boolTag(tagBool, f.getBool(p))
		}
	}
}

// policyList frames the full policy set with the shared list shape, led by
// the policy-list tag so a policy set can never collide with a string list
// whose concatenated bytes happen to match.
func (e *fingerprintEncoder) policyList(policies []Policy) {
	e.tag(tagPolicyList)
	writeListShape(e, policies, e.policy)
}

func (e *fingerprintEncoder) change(c *PolicyChange) {
	e.tag(tagChange)
	// A nil pointer is encoded as tagChange alone; a present value's
	// fields follow immediately.
	if c == nil {
		return
	}
	// Field order comes from the single policy-change field table, so the
	// fingerprint, the UTF-8 decision, the archive and the detaching copy
	// enumerate fields in exactly one place. No change field is skipped.
	for i := range changeFields {
		f := &changeFields[i]
		switch f.kind {
		case changeFieldInt:
			e.int64Tag(tagSeq, int64(f.getInt(c)))
		case changeFieldPolicyList:
			e.policyList(f.getPolicies(c))
		case changeFieldBool:
			e.boolTag(tagBool, f.getBool(c))
		}
	}
}

func (e *fingerprintEncoder) decisionRecord(d *DecisionRecord) {
	e.tag(tagDecisionRecord)
	if d == nil {
		return
	}
	// Field order and the subject/resource/decision group markers all come
	// from the single decision field table, so the fingerprint, the UTF-8
	// decision and the archive enumerate fields in exactly one place. No
	// request or decision field is skipped.
	for i := range decisionFields {
		f := &decisionFields[i]
		if f.groupTag != 0 {
			e.tag(f.groupTag)
		}
		switch f.kind {
		case decisionFieldString:
			e.rawString(f.getString(d))
		case decisionFieldStringList:
			e.stringList(f.getList(d))
		case decisionFieldBool:
			e.boolTag(tagBool, f.getBool(d))
		case decisionFieldInt:
			e.int64Tag(tagSeq, int64(f.getInt(d)))
		}
	}
}

// encodeCanonical returns the raw bytes fingerprinted for a record whose
// strings include invalid UTF-8. Every string the record carries reaches
// the output byte-for-byte, at whatever nesting depth or list position it
// occupies. The prefix separates this encoding space from JSON
// fingerprints. The outer fields come from the single record field table,
// so this encoding enumerates exactly the envelope members the JSON
// encoding and the valid-UTF-8 scan see, in the same order.
func encodeCanonical(r *AuditRecord) []byte {
	e := &fingerprintEncoder{buf: []byte(rawEnvelopePrefix)}
	e.tag(tagEnvelope)
	for i := range recordFields {
		f := &recordFields[i]
		if f.jsonKey == "" {
			// The record's own fingerprint is never an input to itself.
			continue
		}
		switch f.kind {
		case recordFieldString:
			e.rawString(f.getString(r))
		case recordFieldInt:
			e.int64Tag(tagSeq, int64(f.getInt(r)))
		case recordFieldChange:
			e.change(f.getChange(r))
		case recordFieldDecision:
			e.decisionRecord(f.getDecision(r))
		}
	}
	return e.buf
}

// genesisFingerprint derives the chain root from the organization name,
// keeping equal identifiers in different organizations independent.
func genesisFingerprint(org string) string {
	sum := sha256.Sum256([]byte("darksafe-audit-genesis\x00" + org))
	return hex.EncodeToString(sum[:])
}

// encodeJSONEnvelope renders the fingerprint envelope of a record whose
// strings are all valid UTF-8 as the exact byte sequence the historical
// encoding/json envelope struct produced: the envelope members in the
// single record field table's order, every string, integer and payload
// encoded by encoding/json itself, and the two payload members dropped
// when absent exactly as their historical omitempty tags did. Walking the
// table keeps this object in lockstep with the raw canonical encoding, the
// valid-UTF-8 scan and the archive framing by construction.
func encodeJSONEnvelope(r *AuditRecord) []byte {
	var buf []byte
	buf = append(buf, '{')
	first := true
	for i := range recordFields {
		f := &recordFields[i]
		if f.jsonKey == "" {
			// The record's own fingerprint is never an input to itself.
			continue
		}
		var (
			value []byte
			err   error
		)
		switch f.kind {
		case recordFieldString:
			value, err = json.Marshal(f.getString(r))
		case recordFieldInt:
			value, err = json.Marshal(f.getInt(r))
		case recordFieldChange:
			c := f.getChange(r)
			if c == nil {
				continue
			}
			value, err = json.Marshal(c)
		case recordFieldDecision:
			d := f.getDecision(r)
			if d == nil {
				continue
			}
			value, err = json.Marshal(d)
		}
		if err != nil {
			// All envelope values are plain, JSON-encodable values; a
			// failure here indicates a programming error, not user input.
			panic(fmt.Errorf("darksafe: audit envelope must encode: %w", err))
		}
		if !first {
			buf = append(buf, ',')
		}
		first = false
		buf = append(buf, '"')
		buf = append(buf, f.jsonKey...)
		buf = append(buf, '"', ':')
		buf = append(buf, value...)
	}
	return append(buf, '}')
}

// fingerprintFor returns the fingerprint for a record. Records made
// exclusively of valid UTF-8 keep the historical JSON fingerprint, so old
// exports and checkpoints remain valid; records containing invalid bytes
// use the length-prefixed raw encoding that protects their exact bytes.
// Both families cover exactly the envelope members of the single record
// field table — never the record's own fingerprint.
func fingerprintFor(r *AuditRecord) string {
	if recordUsesRawBytes(r) {
		sum := sha256.Sum256(encodeCanonical(r))
		return hex.EncodeToString(sum[:])
	}
	sum := sha256.Sum256(encodeJSONEnvelope(r))
	return hex.EncodeToString(sum[:])
}

// clonePolicies returns a detached copy of a policy set.
func clonePolicies(in []Policy) []Policy {
	if in == nil {
		return nil
	}
	return append([]Policy(nil), in...)
}

// cloneChange returns a detached copy of a policy-change payload.
func cloneChange(c *PolicyChange) *PolicyChange {
	if c == nil {
		return nil
	}
	cp := *c
	// Detach every list the single policy-change field table carries; the
	// per-list nil-versus-empty handling stays exactly as clonePolicies
	// defines it.
	cloneChangeLists(&cp, c)
	return &cp
}

// cloneStrings returns a detached copy of a string slice while preserving
// its nil-versus-empty shape: a nil slice stays nil, and every non-nil
// slice, including a non-nil empty slice that still carries spare capacity,
// receives its own backing array. Copying only when len > 0 is not enough:
// a caller may submit make([]string, 0, 4), and aliasing that array into a
// stored record would let an append to one handed-out copy overwrite the
// first element of every other copy that shares it.
func cloneStrings(in []string) []string {
	if in == nil {
		return nil
	}
	return append([]string{}, in...)
}

// cloneDecision returns a detached copy of a decision payload.
func cloneDecision(d *DecisionRecord) *DecisionRecord {
	if d == nil {
		return nil
	}
	cp := *d
	// Detach every list the single decision field table carries, on non-nil
	// rather than on len > 0 so empty-but-capacious lists are independent
	// copies too; nil lists stay nil.
	cloneDecisionLists(&cp, d)
	return &cp
}

// cloneRecord returns a fully detached copy of a record.
func cloneRecord(r *AuditRecord) *AuditRecord {
	cp := *r
	cp.Change = cloneChange(r.Change)
	cp.Decision = cloneDecision(r.Decision)
	return &cp
}

// appendAuditLocked validates, fingerprints and stores one record. It runs
// under the store mutex and is the single place records are created.
func (st *orgState) appendAuditLocked(org, kind string, change *PolicyChange, decision *DecisionRecord) *AuditRecord {
	seq := len(st.audit) + 1
	prev := genesisFingerprint(org)
	if len(st.audit) > 0 {
		prev = st.audit[len(st.audit)-1].Fingerprint
	}
	// Store detached copies; later caller mutation must not reach the chain.
	rec := &AuditRecord{
		Org:             org,
		Seq:             seq,
		Kind:            kind,
		Change:          cloneChange(change),
		Decision:        cloneDecision(decision),
		PrevFingerprint: prev,
	}
	rec.Fingerprint = fingerprintFor(rec)
	st.audit = append(st.audit, rec)
	return cloneRecord(rec)
}

// auditHeadLocked returns the highest sequence in the chain and the
// fingerprint that covers it: (0, genesis) for an organization with no
// records.
func (st *orgState) auditHeadLocked(org string) (int, string) {
	if len(st.audit) == 0 {
		return 0, genesisFingerprint(org)
	}
	last := st.audit[len(st.audit)-1]
	return last.Seq, last.Fingerprint
}

// Checkpoint pins an audit query to an exact point in a chain.
type Checkpoint struct {
	Org         string
	EndSeq      int
	Fingerprint string
}

// AuditPage is one stable slice of an organization's audit chain.
type AuditPage struct {
	Org     string
	Records []AuditRecord
	// BeginSeq/EndSeq delimit the whole pinned range, not just this page.
	BeginSeq int
	EndSeq   int
	// Next is the first sequence of the following page, 0 when exhausted.
	Next int
	// Checkpoint is the pinned upper bound shared by every page.
	Checkpoint Checkpoint
}

// recordMatches reports whether a record survives the query filters. Every
// set filter is a conjunction: kind, subject and resource conditions must
// all hold. Empty filter values mean "not set".
func recordMatches(r *AuditRecord, kind, subjectID, resourceID string) bool {
	if kind != "" && r.Kind != kind {
		return false
	}
	if subjectID != "" {
		// A subject filter selects decision records of that subject only.
		if r.Kind != AuditDecision || r.Decision == nil ||
			r.Decision.Request.Subject.ID != subjectID {
			return false
		}
	}
	if resourceID != "" {
		// A resource filter selects decision records whose request named
		// exactly this resource. Policy-change records never match, even when
		// a published policy carries the identical ResourceID: the condition
		// reads the requested resource, not policy content. The comparison is
		// Go string equality over the stored raw bytes, so case, surrounding
		// and internal spaces, control bytes and invalid UTF-8 are all
		// significant, and no path or wildcard is interpreted.
		if r.Kind != AuditDecision || r.Decision == nil ||
			r.Decision.Request.Resource.ID != resourceID {
			return false
		}
	}
	return true
}

// optionalResourceCondition extracts the optional resource condition passed
// as the trailing variadic argument. An absent argument or an empty string
// means "no resource filter"; supplying more than one condition is a caller
// error rather than a silently picked value.
func optionalResourceCondition(conds []string) (string, error) {
	switch len(conds) {
	case 0:
		return "", nil
	case 1:
		return conds[0], nil
	default:
		return "", fmt.Errorf("%w: at most one resource condition may be set, got %d", ErrInvalidPage, len(conds))
	}
}

// AuditQuery pins the first page of an audit query. startSeq is the first
// sequence considered (1 from the beginning); endSeq <= 0 means "everything
// currently stored". The returned checkpoint must be passed to AuditPage
// for the following pages, so records appended after the first query never
// mix into later pages.
//
// kind and subjectID are the existing optional filters (empty means unset):
// kind selects a record category and subjectID selects one subject's
// decision records. The optional trailing resourceID adds a resource
// condition, empty or absent meaning unset: only decision records whose
// requested resource ID equals it byte-for-byte survive — case sensitive,
// spaces and control bytes significant, no path or wildcard interpretation,
// invalid UTF-8 kept as-is — and policy-change records never survive it,
// even when a published policy names the same resource ID. Every set
// condition applies together. A resource filter changes only which records
// are returned: paging, checkpoints and detached copies behave exactly as
// without it, and omitting it preserves the historical call and its results.
func (s *Store) AuditQuery(org string, startSeq, pageSize int, kind, subjectID string, resourceID ...string) (*AuditPage, error) {
	resource, err := optionalResourceCondition(resourceID)
	if err != nil {
		return nil, err
	}
	if org == "" {
		return nil, ErrMissingOrganization
	}
	if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
		return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
	}
	if pageSize <= 0 {
		return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
	}
	if startSeq < 1 {
		return nil, fmt.Errorf("%w: start sequence must be >= 1, got %d", ErrInvalidPage, startSeq)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	end, fingerprint := st.auditHeadLocked(org)
	cp := Checkpoint{Org: org, EndSeq: end, Fingerprint: fingerprint}
	if end == 0 {
		// An organization with no records always yields the empty genesis
		// page, regardless of where the caller asked to begin.
		return &AuditPage{Org: org, BeginSeq: 1, EndSeq: 0, Checkpoint: cp}, nil
	}
	if startSeq > end {
		return nil, fmt.Errorf("%w: start sequence %d is beyond end sequence %d", ErrInvalidRange, startSeq, end)
	}
	return s.auditPageLocked(org, startSeq, end, fingerprint, pageSize, kind, subjectID, resource), nil
}

// AuditPage returns one page of a previously pinned query. nextSeq is the
// cursor from the previous page; when it is 0 the range is exhausted. The
// checkpoint is re-verified against the chain on every call.
//
// The filters are the same as AuditQuery's and must agree with the pinned
// query: pass the same kind, subjectID and optional resourceID on every
// page. The resource condition is an exact raw-byte match over requested
// resource IDs and excludes policy-change records, exactly as on the first
// page; omitting it keeps the historical call and result shape.
func (s *Store) AuditPage(cp Checkpoint, nextSeq, pageSize int, kind, subjectID string, resourceID ...string) (*AuditPage, error) {
	resource, err := optionalResourceCondition(resourceID)
	if err != nil {
		return nil, err
	}
	if cp.Org == "" {
		return nil, ErrMissingOrganization
	}
	if kind != "" && kind != AuditPolicyChange && kind != AuditDecision {
		return nil, fmt.Errorf("%w: unknown category %q", ErrInvalidPage, kind)
	}
	if pageSize <= 0 {
		return nil, fmt.Errorf("%w: page size must be positive, got %d", ErrInvalidPage, pageSize)
	}
	if nextSeq < 0 {
		return nil, fmt.Errorf("%w: next sequence must be >= 0, got %d", ErrInvalidPage, nextSeq)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st, ok := s.orgs[cp.Org]
	if !ok {
		// No organization state: the only valid checkpoint is an empty one.
		g := genesisFingerprint(cp.Org)
		if cp.EndSeq == 0 && cp.Fingerprint == g && nextSeq == 0 {
			return &AuditPage{Org: cp.Org, BeginSeq: 0, EndSeq: 0, Checkpoint: cp}, nil
		}
		return nil, fmt.Errorf("%w: checkpoint organization has no records", ErrInvalidRange)
	}
	head := len(st.audit)
	if cp.EndSeq < 0 || cp.EndSeq > head {
		return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
	}
	wantFP := genesisFingerprint(cp.Org)
	if cp.EndSeq > 0 {
		if cp.EndSeq > len(st.audit) {
			return nil, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, cp.EndSeq, head)
		}
		wantFP = st.audit[cp.EndSeq-1].Fingerprint
	}
	if cp.Fingerprint != wantFP {
		return nil, fmt.Errorf("%w: checkpoint fingerprint does not match the chain at sequence %d", ErrInvalidRange, cp.EndSeq)
	}
	if nextSeq == 0 {
		return &AuditPage{Org: cp.Org, BeginSeq: 1, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
	}
	if nextSeq > cp.EndSeq+1 {
		return nil, fmt.Errorf("%w: next sequence %d beyond pinned range ending at %d", ErrInvalidRange, nextSeq, cp.EndSeq)
	}
	if nextSeq == cp.EndSeq+1 {
		return &AuditPage{Org: cp.Org, BeginSeq: nextSeq, EndSeq: cp.EndSeq, Checkpoint: cp}, nil
	}
	return s.auditPageLocked(cp.Org, nextSeq, cp.EndSeq, wantFP, pageSize, kind, subjectID, resource), nil
}

// auditPageLocked scans forward collecting up to pageSize matching records
// and computes the next-page cursor. It does not stop at pageSize raw
// records: filtering happens within the pinned [start,end] window, so
// non-matching records between matches — including policy changes excluded
// by a resource condition — never consume page slots.
func (s *Store) auditPageLocked(org string, startSeq, endSeq int, endFP string, pageSize int, kind, subjectID, resourceID string) *AuditPage {
	st := s.orgs[org]
	// pageSize only bounds how many records this page returns; it must not
	// drive allocation. A caller may pass any positive value, including the
	// largest int, for a range holding a handful of records, so preallocate
	// no more than the window can actually contain.
	window := endSeq - startSeq + 1
	capHint := pageSize
	if window < capHint {
		capHint = window
	}
	out := make([]AuditRecord, 0, capHint)
	i := startSeq
	for ; i <= endSeq && len(out) < pageSize; i++ {
		r := st.audit[i-1]
		if recordMatches(r, kind, subjectID, resourceID) {
			out = append(out, *cloneRecord(r))
		}
	}
	next := 0
	if i <= endSeq {
		next = i
	}
	return &AuditPage{
		Org:        org,
		Records:    out,
		BeginSeq:   startSeq,
		EndSeq:     endSeq,
		Next:       next,
		Checkpoint: Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: endFP},
	}
}

// AuditExport returns detached copies of the complete records through
// endSeq, suitable for offline verification. endSeq <= 0 means everything
// currently stored. An organization with no records yields an empty slice
// together with its sequence-0 checkpoint.
func (s *Store) AuditExport(org string, endSeq int) (records []AuditRecord, cp Checkpoint, err error) {
	if org == "" {
		return nil, Checkpoint{}, ErrMissingOrganization
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st := s.orgLocked(org)
	head := len(st.audit)
	if endSeq <= 0 {
		endSeq = head
	}
	if endSeq > head {
		return nil, Checkpoint{}, fmt.Errorf("%w: end sequence %d beyond %d", ErrInvalidRange, endSeq, head)
	}
	if endSeq < 0 {
		return nil, Checkpoint{}, fmt.Errorf("%w: end sequence must be >= 0, got %d", ErrInvalidPage, endSeq)
	}
	// The checkpoint fingerprints the final exported record, not the
	// possibly later current head.
	fingerprint := genesisFingerprint(org)
	if endSeq > 0 {
		fingerprint = st.audit[endSeq-1].Fingerprint
	}
	out := make([]AuditRecord, 0, endSeq)
	for i := 0; i < endSeq; i++ {
		out = append(out, *cloneRecord(st.audit[i]))
	}
	return out, Checkpoint{Org: org, EndSeq: endSeq, Fingerprint: fingerprint}, nil
}

// VerifyAudit validates an exported record set entirely without a Store.
// The caller separately retains the organization, end sequence and
// fingerprint they expect. It rejects any modified field, missing middle or
// tail record, swapped order, and record spliced in from another
// organization. Empty or nil records validate exactly when the checkpoint
// is the organization's genesis (end sequence 0).
func VerifyAudit(org string, records []AuditRecord, cp Checkpoint) error {
	if org == "" {
		return ErrMissingOrganization
	}
	if cp.Org != "" && cp.Org != org {
		return fmt.Errorf("%w: checkpoint organization %q does not match %q", ErrInvalidRange, cp.Org, org)
	}
	genesis := genesisFingerprint(org)
	if len(records) == 0 {
		if cp.EndSeq != 0 || cp.Fingerprint != genesis {
			return fmt.Errorf("%w: empty records but checkpoint claims end sequence %d", ErrInvalidRange, cp.EndSeq)
		}
		return nil
	}
	if cp.EndSeq != len(records) {
		return fmt.Errorf("%w: have %d records, checkpoint ends at %d", ErrInvalidRange, len(records), cp.EndSeq)
	}
	prev := genesis
	for i, r := range records {
		wantSeq := i + 1
		if r.Org != org {
			return fmt.Errorf("%w: record %d belongs to organization %q", ErrInvalidRange, wantSeq, r.Org)
		}
		if r.Seq != wantSeq {
			return fmt.Errorf("%w: record %d has sequence %d", ErrInvalidRange, wantSeq, r.Seq)
		}
		if r.PrevFingerprint != prev {
			return fmt.Errorf("%w: record %d breaks the chain", ErrInvalidRange, wantSeq)
		}
		wantFP := fingerprintFor(&r)
		if r.Fingerprint != wantFP {
			return fmt.Errorf("%w: record %d fingerprint mismatch", ErrInvalidRange, wantSeq)
		}
		if r.Kind == AuditPolicyChange {
			if r.Change == nil || r.Decision != nil {
				return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
			}
		} else if r.Kind == AuditDecision {
			if r.Decision == nil || r.Change != nil {
				return fmt.Errorf("%w: record %d payload does not match its category", ErrInvalidRange, wantSeq)
			}
		} else {
			return fmt.Errorf("%w: record %d has unknown category %q", ErrInvalidRange, wantSeq, r.Kind)
		}
		prev = r.Fingerprint
	}
	last := records[len(records)-1]
	if last.Fingerprint != cp.Fingerprint {
		return fmt.Errorf("%w: checkpoint fingerprint does not match the final record", ErrInvalidRange)
	}
	return nil
}

// RecheckDecision re-evaluates the request stored in an organization's
// decision record against the policy version that decision actually used.
// Later publishes or rollbacks cannot alter the result. Non-decision
// records and missing sequences return distinguishable errors.
//
// The record and the version snapshot come exclusively from this
// organization's own live history; the version-zero and historical-policy
// judgment itself is shared with RecheckDecisionOffline in
// replayRecordedDecision.
func (s *Store) RecheckDecision(org string, seq int) (Decision, error) {
	if org == "" {
		return Decision{}, ErrMissingOrganization
	}
	if seq < 1 {
		return Decision{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	st, ok := s.orgs[org]
	if !ok || seq > len(st.audit) {
		return Decision{}, fmt.Errorf("%w: organization %q has no audit sequence %d", ErrAuditNotFound, org, seq)
	}
	rec := st.audit[seq-1]
	if rec.Kind != AuditDecision || rec.Decision == nil {
		return Decision{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
	}
	req := rec.Decision.Request
	version := rec.Decision.Decision.Version
	resolve := func(version int) versionPolicies {
		src, ok := st.versions[version]
		if !ok {
			// A decision's version is immutable and never deleted; its
			// absence indicates store tampering rather than normal
			// operation.
			return versionPolicies{status: replayVersionAbsent}
		}
		// Live snapshots are immutable; detach anyway so the returned
		// decision can never share storage with the store.
		return versionPolicies{policies: append([]Policy(nil), src...)}
	}
	d, status := replayRecordedDecision(org, req, version, resolve)
	if status == replayVersionAbsent {
		return Decision{}, fmt.Errorf("%w: decision used version %d, which no longer exists", ErrVersionNotFound, version)
	}
	return d, nil
}

// This file implements lossless archiving of one organization's audit
// export. AuditExport hands back detached in-memory records and the caller
// separately retains the checkpoint pinning them; an archive serializes the
// export so it can be saved to a file when the service instance ends and
// read back later, still paired with the caller's own checkpoint and still
// usable as the material for RecheckDecisionOffline.
//
// The format is a length-delimited binary encoding built by hand rather
// than encoding/json: JSON text cannot carry bytes that are not valid
// UTF-8 without silently replacing them with U+FFFD, which would collapse
// genuinely different content (a lone 0xFF, a lone 0xFE and a real U+FFFD)
// onto identical records and change their fingerprints. Every string is
// written from its exact bytes with a length prefix, and nil slices,
// non-nil empty slices and absent payloads are each marked explicitly.
//
// Integrity never comes from trust in the file. A decode reconstructs the
// records and then runs the same whole-material VerifyAudit chain check
// against the checkpoint the caller supplies independently; the checkpoint
// embedded in the archive is informational only and never authoritative.
package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"fmt"
)

// ErrInvalidArchive means archive bytes are not a recognizable, complete,
// untampered audit archive: a foreign/truncated/trailing-byte framing, a
// failed checksum, or content that does not decode. Content-level failures
// (missing or mismatched organization, missing, out-of-order or modified
// records, a mismatched checkpoint) keep using ErrMissingOrganization and
// ErrInvalidRange exactly as the other audit entry points do.
var ErrInvalidArchive = errors.New("darksafe: invalid audit archive")

// Archive framing:
//
//	magic   = archiveMagic
//	u32 BE  = byte length of the payload that follows
//	payload = archivePayloadLen bytes
//	32 bytes = SHA-256 checksum of payload
//
// A second archive concatenated to a first is trailing material, not a
// second frame: a read consumes exactly one frame and rejects any byte
// beyond it.
const archiveMagic = "darksafe-audit-archive-v1\n"

const (
	archiveTagBoolFalse byte = 0
	archiveTagBoolTrue  byte = 1
	archiveTagNil       byte = 0
	archiveTagPresent   byte = 1
)

// archiveWriter appends length-delimited fields to a byte buffer.
type archiveWriter struct {
	buf []byte
	err error
}

func (w *archiveWriter) raw(data []byte) {
	w.buf = append(w.buf, data...)
}

// u32 writes a non-negative int as a big-endian uint32.
func (w *archiveWriter) u32(v int) {
	if v < 0 || uint64(v) > 0xffffffff {
		w.err = fmt.Errorf("%w: length out of range: %d", ErrInvalidArchive, v)
		return
	}
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], uint32(v))
	w.buf = append(w.buf, b[:]...)
}

func (w *archiveWriter) boolean(v bool) {
	if v {
		w.buf = append(w.buf, archiveTagBoolTrue)
	} else {
		w.buf = append(w.buf, archiveTagBoolFalse)
	}
}

// put appends one raw framing byte. It is the archive sink's side of the
// shared list shape: the list presence marker (archiveTagNil for nil,
// archiveTagPresent for a non-nil list) goes into the payload verbatim.
func (w *archiveWriter) put(b byte) {
	w.buf = append(w.buf, b)
}

// listCount writes a list element count through the archive's own
// range-checked u32, so a list length the uint32 format cannot represent
// still fails the whole archive with the existing ErrInvalidArchive rather
// than emitting truncated framing or returning partial bytes.
func (w *archiveWriter) listCount(n int) {
	w.u32(n)
}

// stringField writes a string from its exact memory bytes. Nothing is
// validated, replaced or normalized: a lone 0xFF reaches the output as
// itself and stays distinguishable from 0xFE and a genuine U+FFFD.
func (w *archiveWriter) stringField(s string) {
	w.u32(len(s))
	if w.err != nil {
		return
	}
	w.buf = append(w.buf, s...)
}

// policy writes one Policy by walking the single policy field table, so the
// archive's field order is the fingerprint's order by construction. Even the
// fingerprint-optional ResourceID is always written here (empty included),
// so every field round trips on its own; its placement is fixed by the
// table and therefore cannot move a fingerprint boundary.
func (w *archiveWriter) policy(p Policy) {
	for i := range policyFields {
		f := &policyFields[i]
		switch f.kind {
		case policyFieldString, policyFieldOptionalString:
			w.stringField(f.getString(p))
		case policyFieldBool:
			w.boolean(f.getBool(p))
		}
	}
}

// change writes the policy-change payload, or a single absence marker:
// VerifyAudit only ever accepts a change payload on a policy-change record
// and its absence otherwise, but the distinction is encoded explicitly so
// decode never has to reconstruct a shape. A present payload walks the
// single policy-change field table, so the archive's field order is the
// fingerprint's order by construction and every change field round trips.
func (w *archiveWriter) change(c *PolicyChange) {
	if c == nil {
		w.buf = append(w.buf, archiveTagNil)
		return
	}
	w.buf = append(w.buf, archiveTagPresent)
	for i := range changeFields {
		f := &changeFields[i]
		switch f.kind {
		case changeFieldInt:
			w.u32(f.getInt(c))
		case changeFieldPolicyList:
			writeListShape(w, f.getPolicies(c), w.policy)
		case changeFieldBool:
			w.boolean(f.getBool(c))
		}
	}
}

// decisionRecord writes the decision payload, or a single absence marker:
// VerifyAudit only ever accepts a decision payload on a decision record and
// its absence otherwise, but the distinction is encoded explicitly so decode
// never has to reconstruct a shape. A present payload walks the single
// decision field table, so the archive's field order is the fingerprint's
// order by construction and every request and decision field round trips.
func (w *archiveWriter) decisionRecord(d *DecisionRecord) {
	if d == nil {
		w.buf = append(w.buf, archiveTagNil)
		return
	}
	w.buf = append(w.buf, archiveTagPresent)
	for i := range decisionFields {
		f := &decisionFields[i]
		switch f.kind {
		case decisionFieldString:
			w.stringField(f.getString(d))
		case decisionFieldStringList:
			writeListShape(w, f.getList(d), w.stringField)
		case decisionFieldBool:
			w.boolean(f.getBool(d))
		case decisionFieldInt:
			w.u32(f.getInt(d))
		}
	}
}

// EncodeAuditArchive serializes one complete audit export into savable
// bytes. org is the organization name, records is its complete chain from
// sequence 1 (a valid prefix ending at some historical sequence is enough,
// provided cp pins exactly that sequence), and cp is the checkpoint the
// caller separately retains. An organization with no records archives too:
// records is empty and cp is its sequence-0 genesis checkpoint.
//
// The whole material is validated exactly as VerifyAudit would before any
// bytes are returned: a missing organization is ErrMissingOrganization, and
// a missing, out-of-order or foreign record, modified content or checkpoint
// mismatch is ErrInvalidRange. On failure no archive bytes are returned.
// The checkpoint is carried in the archive for reference, but never stands
// in for the separately retained evidence: DecodeAuditArchive always
// validates against the checkpoint handed to it. The call is read-only:
// neither the records nor any service state are mutated and no audit record
// is appended.
func EncodeAuditArchive(org string, records []AuditRecord, cp Checkpoint) ([]byte, error) {
	if org == "" {
		return nil, ErrMissingOrganization
	}
	if err := VerifyAudit(org, records, cp); err != nil {
		return nil, err
	}

	pw := &archiveWriter{}
	pw.stringField(org)
	pw.u32(cp.EndSeq)
	pw.stringField(cp.Fingerprint)
	pw.u32(len(records))
	for i := range records {
		rec := &records[i]
		// The outer record fields walk the single record field table, so
		// the archive's record layout is the fingerprint envelope's layout
		// — plus the record's own fingerprint, which the envelope excludes
		// — by construction, and no outer field can be skipped or
		// reordered here alone.
		for j := range recordFields {
			f := &recordFields[j]
			switch f.kind {
			case recordFieldString:
				pw.stringField(f.getString(rec))
			case recordFieldInt:
				pw.u32(f.getInt(rec))
			case recordFieldChange:
				pw.change(f.getChange(rec))
			case recordFieldDecision:
				pw.decisionRecord(f.getDecision(rec))
			}
		}
	}
	if pw.err != nil {
		return nil, pw.err
	}
	payload := pw.buf

	out := make([]byte, 0, len(archiveMagic)+4+len(payload)+sha256.Size)
	out = append(out, archiveMagic...)
	var lenBuf [4]byte
	binary.BigEndian.PutUint32(lenBuf[:], uint32(len(payload)))
	out = append(out, lenBuf[:]...)
	out = append(out, payload...)
	sum := sha256.Sum256(payload)
	out = append(out, sum[:]...)
	return out, nil
}

// archiveReader walks one payload without copying string contents: string
// fields are backed by the payload slice itself, which is owned by the
// decoder and never returned, so callers cannot mutate the input through
// the result.
type archiveReader struct {
	data []byte
	pos  int
	err  error
}

func (r *archiveReader) need(n int) bool {
	if r.err != nil {
		return false
	}
	if n < 0 || r.pos > len(r.data)-n {
		r.err = fmt.Errorf("%w: truncated archive payload", ErrInvalidArchive)
		return false
	}
	return true
}

func (r *archiveReader) marker() byte {
	if !r.need(1) {
		return 0
	}
	b := r.data[r.pos]
	r.pos++
	return b
}

func (r *archiveReader) u32() int {
	if !r.need(4) {
		return 0
	}
	v := int(binary.BigEndian.Uint32(r.data[r.pos : r.pos+4]))
	r.pos += 4
	return v
}

// boundedCount reads a count and proves at least minBytesPerItem bytes
// remain per item, so a hostile payload cannot drive a huge allocation
// with a count its body could never satisfy.
func (r *archiveReader) boundedCount(minBytesPerItem int) int {
	n := r.u32()
	if r.err != nil {
		return 0
	}
	if n < 0 || uint64(n)*uint64(minBytesPerItem) > uint64(len(r.data)-r.pos) {
		r.err = fmt.Errorf("%w: implausible list count %d", ErrInvalidArchive, n)
		return 0
	}
	return n
}

func (r *archiveReader) boolean() bool {
	switch r.marker() {
	case archiveTagBoolTrue:
		return true
	case archiveTagBoolFalse:
		return false
	default:
		if r.err == nil {
			r.err = fmt.Errorf("%w: invalid boolean marker", ErrInvalidArchive)
		}
		return false
	}
}

func (r *archiveReader) stringField() string {
	n := r.u32()
	if r.err != nil {
		return ""
	}
	if !r.need(n) {
		return ""
	}
	// Conversion copies the bytes, so the result never aliases the input.
	s := string(r.data[r.pos : r.pos+n])
	r.pos += n
	return s
}

// readList reads one length-counted list framed by writeListShape on the
// archive sink, whatever its item type: both string lists and the policy
// list decode here. Every list
// kind gets the exact same framing checks — the nil/presence marker, the
// per-item byte floor before any allocation, and each item's own
// truncation/structure errors — so a hostile count can neither drive a
// disproportionate allocation nor deliver a partial list: once an item
// fails, the reader's sticky error fails the whole read.
// minBytesPerItem is the minimum an item could occupy (each string item
// carries one length word; a policy item carries six length words and a
// bool), and is used only to reject counts the remaining bytes could never
// satisfy.
func readList[T any](r *archiveReader, minBytesPerItem int, readItem func() T) []T {
	switch r.marker() {
	case archiveTagNil:
		return nil
	case archiveTagPresent:
	default:
		if r.err == nil {
			r.err = fmt.Errorf("%w: invalid list marker", ErrInvalidArchive)
		}
		return nil
	}
	n := r.boundedCount(minBytesPerItem)
	if r.err != nil {
		return nil
	}
	items := make([]T, n)
	for i := range items {
		items[i] = readItem()
	}
	return items
}

func (r *archiveReader) policy() Policy {
	// Read fields in the single table's (write and fingerprint) order. The
	// fingerprint-optional ResourceID is still a mandatory, fixed field on
	// the archive, so it is read for every policy including the empty one.
	var p Policy
	for i := range policyFields {
		f := &policyFields[i]
		switch f.kind {
		case policyFieldString, policyFieldOptionalString:
			f.setString(&p, r.stringField())
		case policyFieldBool:
			f.setBool(&p, r.boolean())
		}
	}
	return p
}

func (r *archiveReader) change() *PolicyChange {
	switch r.marker() {
	case archiveTagNil:
		return nil
	case archiveTagPresent:
	default:
		if r.err == nil {
			r.err = fmt.Errorf("%w: invalid change payload marker", ErrInvalidArchive)
		}
		return nil
	}
	// Read fields in the single table's (write and fingerprint) order, so a
	// field can never be restored into the wrong member or skipped.
	c := &PolicyChange{}
	for i := range changeFields {
		f := &changeFields[i]
		switch f.kind {
		case changeFieldInt:
			f.setInt(c, r.u32())
		case changeFieldPolicyList:
			// A policy writes six length words (five strings plus
			// ResourceID) and one bool byte at minimum.
			f.setPolicies(c, readList(r, 6*4+1, r.policy))
		case changeFieldBool:
			f.setBool(c, r.boolean())
		}
	}
	return c
}

func (r *archiveReader) decisionRecord() *DecisionRecord {
	switch r.marker() {
	case archiveTagNil:
		return nil
	case archiveTagPresent:
	default:
		if r.err == nil {
			r.err = fmt.Errorf("%w: invalid decision payload marker", ErrInvalidArchive)
		}
		return nil
	}
	// Read fields in the single table's (write and fingerprint) order, so a
	// field can never be restored into the wrong member or skipped.
	d := &DecisionRecord{}
	for i := range decisionFields {
		f := &decisionFields[i]
		switch f.kind {
		case decisionFieldString:
			f.setString(d, r.stringField())
		case decisionFieldStringList:
			// Each string item carries at least one length word.
			f.setList(d, readList(r, 4, r.stringField))
		case decisionFieldBool:
			f.setBool(d, r.boolean())
		case decisionFieldInt:
			f.setInt(d, r.u32())
		}
	}
	return d
}

// decodedArchiveFrame is one archive parsed up to, but not including, the
// content checks: the reconstructed records and the informational
// checkpoint embedded in the header. Nothing at this stage has been
// validated against the caller's organization or retained checkpoint.
type decodedArchiveFrame struct {
	records     []AuditRecord
	org         string
	endSeq      int
	fingerprint string
}

// decodeAuditArchiveFrame parses one frame's framing, checksum and payload.
// It performs no content validation: the embedded organization and
// checkpoint are returned for the caller to compare, and the records are
// not chain-checked until a content-validating entry point runs the single
// VerifyAudit pass.
func decodeAuditArchiveFrame(archive []byte) (decodedArchiveFrame, error) {
	magicLen := len(archiveMagic)
	if len(archive) < magicLen+4+sha256.Size || string(archive[:magicLen]) != archiveMagic {
		return decodedArchiveFrame{}, fmt.Errorf("%w: unrecognized audit archive", ErrInvalidArchive)
	}
	pos := magicLen
	payloadLen := int(binary.BigEndian.Uint32(archive[pos : pos+4]))
	pos += 4
	checksumEnd := pos + payloadLen
	if payloadLen < 0 || checksumEnd+sha256.Size != len(archive) {
		// A short frame is truncation; bytes beyond the one frame (a
		// concatenated second archive, junk appended to a good file) are a
		// framing failure too.
		return decodedArchiveFrame{}, fmt.Errorf("%w: truncated or trailing audit archive bytes", ErrInvalidArchive)
	}
	payload := archive[pos:checksumEnd]
	sum := sha256.Sum256(payload)
	if !bytes.Equal(sum[:], archive[checksumEnd:checksumEnd+sha256.Size]) {
		return decodedArchiveFrame{}, fmt.Errorf("%w: checksum mismatch", ErrInvalidArchive)
	}

	r := &archiveReader{data: payload}
	embeddedOrg := r.stringField()
	embeddedEndSeq := r.u32()
	embeddedFingerprint := r.stringField()
	// Every record writes two payload markers, a sequence word, two
	// fingerprint length words and org/kind length words: 22 bytes even
	// when every string is empty.
	n := r.boundedCount(22)
	if r.err != nil {
		return decodedArchiveFrame{}, r.err
	}
	records := make([]AuditRecord, 0, n)
	for i := 0; i < n; i++ {
		// Read the outer fields in the single record field table's (write
		// and fingerprint) order, so a field can never be restored into the
		// wrong member or skipped.
		var rec AuditRecord
		for j := range recordFields {
			f := &recordFields[j]
			switch f.kind {
			case recordFieldString:
				f.setString(&rec, r.stringField())
			case recordFieldInt:
				f.setInt(&rec, r.u32())
			case recordFieldChange:
				f.setChange(&rec, r.change())
			case recordFieldDecision:
				f.setDecision(&rec, r.decisionRecord())
			}
		}
		records = append(records, rec)
	}
	if r.err != nil {
		return decodedArchiveFrame{}, r.err
	}
	if r.pos != len(payload) {
		return decodedArchiveFrame{}, fmt.Errorf("%w: %d unconsumed archive bytes", ErrInvalidArchive, len(payload)-r.pos)
	}
	return decodedArchiveFrame{
		records:     records,
		org:         embeddedOrg,
		endSeq:      embeddedEndSeq,
		fingerprint: embeddedFingerprint,
	}, nil
}

// validateDecodedFrame applies the content checks to a parsed frame and
// returns the material as VerifiedAuditMaterial after the single complete
// VerifyAudit chain pass. The embedded checkpoint is informational; still,
// contradicting the retained checkpoint means the payload was altered, and
// the authoritative check always uses the caller's independently retained
// checkpoint.
func validateDecodedFrame(frame decodedArchiveFrame, org string, cp Checkpoint) (VerifiedAuditMaterial, error) {
	// Content checks reuse the exact audit-range validation the live export
	// and offline review paths use, so an archive can never smuggle in a
	// shape those entry points would reject.
	if frame.org != org {
		return VerifiedAuditMaterial{}, fmt.Errorf("%w: archive organization %q does not match %q", ErrInvalidRange, frame.org, org)
	}
	if frame.endSeq != cp.EndSeq || frame.fingerprint != cp.Fingerprint {
		return VerifiedAuditMaterial{}, fmt.Errorf("%w: embedded checkpoint does not match the retained checkpoint", ErrInvalidRange)
	}
	return verifyAuditMaterial(org, frame.records, cp)
}

// DecodeVerifiedAuditArchive reads one archive produced by
// EncodeAuditArchive, validates it once, and returns the material ready
// for RecheckVerifiedDecisionOffline. It is the single-validation half of
// the offline review flow: the returned VerifiedAuditMaterial carries the
// already-checked chain, so the following review performs no second chain
// pass. org is the organization the caller expects, and cp is the
// checkpoint the caller independently retained; the checkpoint embedded in
// the file is never treated as evidence, so even an archive carrying a
// plausible checkpoint only validates against the one supplied here.
//
// A missing organization is ErrMissingOrganization. Unrecognized framing,
// truncation, a trailing second archive or any other extra byte, a bad
// checksum, and undecodable content are ErrInvalidArchive. Records that
// decode but are missing, out of order, foreign to the organization,
// modified (including a record after the one the caller intends to review)
// or mismatched with the supplied checkpoint fail the whole read with
// ErrInvalidRange. Failure returns no material. A successful read only
// proves the material matches the checkpoint: an original decision that
// disagrees with a recomputed one is reported later by offline review, not
// treated as archive damage. The material is detached from archive
// (mutating one never reaches the other), and the call is read-only.
func DecodeVerifiedAuditArchive(archive []byte, org string, cp Checkpoint) (VerifiedAuditMaterial, error) {
	if org == "" {
		return VerifiedAuditMaterial{}, ErrMissingOrganization
	}
	frame, err := decodeAuditArchiveFrame(archive)
	if err != nil {
		return VerifiedAuditMaterial{}, err
	}
	return validateDecodedFrame(frame, org, cp)
}

// DecodeAuditArchive reads one archive produced by EncodeAuditArchive and
// returns records that can be handed directly to RecheckDecisionOffline.
// org is the organization the caller expects, and cp is the checkpoint the
// caller independently retained; the checkpoint embedded in the file is
// never treated as evidence, so even an archive carrying a plausible
// checkpoint only validates against the one supplied here.
//
// This is a standalone entry point: it performs the complete archive and
// chain validation itself and never assumes another entry point ran first.
// (The `darksafe review` command instead uses DecodeVerifiedAuditArchive
// followed by RecheckVerifiedDecisionOffline, so one invocation validates
// the chain exactly once rather than once here and again in the review.)
//
// A missing organization is ErrMissingOrganization. Unrecognized framing,
// truncation, a trailing second archive or any other extra byte, a bad
// checksum, and undecodable content are ErrInvalidArchive. Records that
// decode but are missing, out of order, foreign to the organization,
// modified (including a record after the one the caller intends to review)
// or mismatched with the supplied checkpoint fail the whole read with
// ErrInvalidRange. Failure returns no records. A successful read only
// proves the material matches the checkpoint: an original decision that
// disagrees with a recomputed one is reported later by offline review, not
// treated as archive damage. The result is detached from archive (mutating
// one never reaches the other), and the call is read-only.
func DecodeAuditArchive(archive []byte, org string, cp Checkpoint) ([]AuditRecord, error) {
	m, err := DecodeVerifiedAuditArchive(archive, org, cp)
	if err != nil {
		return nil, err
	}
	return m.records, nil
}

// This file implements offline review of a single audited decision. It
// works solely from exported audit material: the complete record export,
// the separately retained checkpoint, and a target sequence. No Store is
// created or restored, so an organization can confirm why an access was
// allowed or denied long after the service instance that decided it has
// ended.
//
// The complete input must first validate as an audit chain. The policy
// version a decision actually used is recovered exclusively from policy
// change records preceding that decision within the same organization's
// export; later publishes or rollbacks, and a wider later export, cannot
// change the recomputed result.
//
// A review that already holds the material as decoded records
// (RecheckDecisionOffline) and one that starts from an archive file
// (DecodeAuditArchive followed by a review) historically each ran the full
// VerifyAudit chain check on their own, so `darksafe review` validated the
// same material twice per invocation. The two stages now share one pass:
// VerifyAudit runs exactly once per review, its result is carried in an
// unexported VerifiedAuditMaterial, and the review replays the target from
// that already-verified material without re-checking the chain. The
// standalone entry points keep validating their own inputs, so neither
// requires the caller to have run another entry point first.
package darksafe

import "fmt"

// OfflineDecisionReview compares the decision stored in an audited record
// with a decision recomputed purely from the exported material.
type OfflineDecisionReview struct {
	// Seq is the reviewed decision record's sequence.
	Seq int
	// Original is the decision preserved in the audited record.
	Original Decision
	// Recomputed is the decision evaluated again offline from the saved
	// request and the policy version it originally used.
	Recomputed Decision
	// Consistent reports whether both decisions agree on every field
	// (allowance, reason, matched policies and version), treating a nil
	// matched list and an empty matched list as the same.
	Consistent bool
}

// VerifiedAuditMaterial is an export that has passed the complete
// VerifyAudit chain check against the checkpoint it carries. It is the
// boundary between one validation and the review: an entry point that has
// just validated the material hands it to RecheckVerifiedDecisionOffline,
// and the review replays the target without validating the chain a second
// time.
//
// It is intentionally unexported: it can only be produced by this package's
// own validating entry points (verifyAuditMaterial, reached from
// RecheckDecisionOffline, DecodeAuditArchive and DecodeVerifiedAuditArchive),
// never from a caller's assertion. It carries no memo that survives the
// call that produced it, so modified material or a different checkpoint
// always forces a fresh validation; the embedded records are the caller's
// and stay owned by the caller.
type VerifiedAuditMaterial struct {
	org     string
	records []AuditRecord
	cp      Checkpoint
}

// verifyAuditMaterial validates the whole export exactly as VerifyAudit
// does and, on success, returns it as VerifiedAuditMaterial. It is the
// single place the chain check is performed on the offline review path; a
// failure returns no material, so a later stage can never review records
// that did not validate.
func verifyAuditMaterial(org string, records []AuditRecord, cp Checkpoint) (VerifiedAuditMaterial, error) {
	if verifyAuditObserver != nil {
		verifyAuditObserver()
	}
	if err := VerifyAudit(org, records, cp); err != nil {
		return VerifiedAuditMaterial{}, err
	}
	return VerifiedAuditMaterial{org: org, records: records, cp: cp}, nil
}

// RecheckVerifiedDecisionOffline re-evaluates one decision record from
// material a preceding stage has already chain-validated as one unit
// (verifyAuditMaterial or DecodeVerifiedAuditArchive). It does not run the
// chain check again: one review performs one complete chain validation, and
// tampering anywhere is rejected before this stage is reached. All target
// and replay guarantees are otherwise identical to
// RecheckDecisionOffline's: ErrAuditNotFound for a non-positive or absent
// target sequence, ErrAuditNotADecision when the target is a policy change
// record, and ErrVersionNotFound when the version the decision names has no
// change record before the target (including content that appears only
// after it); a newer version is never substituted. The call is read-only
// and the returned decisions are detached from the material's slices.
func RecheckVerifiedDecisionOffline(m VerifiedAuditMaterial, seq int) (OfflineDecisionReview, error) {
	return recheckVerifiedOffline(m, seq)
}

// recheckVerifiedOffline is the shared review body. It takes an unexported
// verified-material value so only this package's validating stages can
// reach the already-validated path; standalone RecheckDecisionOffline
// validates first and then calls it just as the combined archive flow does.
func recheckVerifiedOffline(m VerifiedAuditMaterial, seq int) (OfflineDecisionReview, error) {
	org, records := m.org, m.records
	if seq < 1 {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d", ErrAuditNotFound, seq)
	}
	if seq > len(records) {
		return OfflineDecisionReview{}, fmt.Errorf("%w: export ends at %d, no sequence %d", ErrAuditNotFound, len(records), seq)
	}
	rec := &records[seq-1]
	if rec.Kind != AuditDecision || rec.Decision == nil {
		return OfflineDecisionReview{}, fmt.Errorf("%w: sequence %d is %s", ErrAuditNotADecision, seq, rec.Kind)
	}

	original := cloneDecisionValue(rec.Decision.Decision)
	req := rec.Decision.Request
	// Detach the request list by non-nil rather than by length: a non-nil
	// empty role list with spare capacity must not be shared back with the
	// caller's material, even though evaluation never reads any element.
	req.Subject.Roles = cloneStrings(req.Subject.Roles)
	version := original.Version

	// The version's full content must travel in a same-organization policy
	// change record positioned before the decision. The replay core resolves
	// the version before replaying any request rule, so a request the
	// envelope rejects cannot mask a missing or later-only version.
	resolve := func(want int) versionPolicies {
		if policies, found := policiesBefore(records, seq-1, want); found {
			return versionPolicies{policies: policies}
		}
		if _, later := policiesBefore(records, len(records), want); later {
			return versionPolicies{status: replayVersionAfterTarget}
		}
		return versionPolicies{status: replayVersionAbsent}
	}
	recomputed, status := replayRecordedDecision(org, req, version, resolve)
	switch status {
	case replayVersionAfterTarget:
		return OfflineDecisionReview{}, fmt.Errorf(
			"%w: decision at sequence %d used version %d, whose change record appears only after it",
			ErrVersionNotFound, seq, version)
	case replayVersionAbsent:
		return OfflineDecisionReview{}, fmt.Errorf(
			"%w: decision at sequence %d used version %d, which has no policy change record in the export",
			ErrVersionNotFound, seq, version)
	}

	return OfflineDecisionReview{
		Seq:        seq,
		Original:   original,
		Recomputed: recomputed,
		Consistent: decisionsEqual(original, recomputed),
	}, nil
}

// RecheckDecisionOffline re-evaluates one decision record offline. org is
// the organization name, records is its complete export starting at
// sequence 1 (a valid prefix is sufficient when paired with its own
// checkpoint), cp is the separately saved checkpoint, and seq identifies
// the decision record to review. The call is read-only: it neither mutates
// the supplied material nor appends audit records, and the returned
// decisions are detached from the input slices.
//
// The entire export is chain-validated in this call before any result is
// produced; tampering anywhere, including in records after the target,
// fails the review. The caller does not need to have validated the
// material through another entry point first: standalone callers receive
// the exact same guarantees DecodeAuditArchive gives, and validation is
// always based on this call's material, organization and checkpoint — a
// previous validation is never reused after the material changes or the
// checkpoint changes. Distinguishable errors follow the other audit entry
// points: ErrMissingOrganization for an empty organization, ErrAuditNotFound
// for a non-positive or absent target sequence, and ErrAuditNotADecision
// when the target is a policy change record. When the saved decision names
// a policy version whose full content has no change record before the
// target, ErrVersionNotFound is returned; a newer version is never
// substituted, and a request the envelope would reject never masks the
// missing version.
//
// The fingerprint only proves the material matches its checkpoint; it
// cannot stand in for evaluating the request itself. So even when the
// declared version exists and carries an otherwise matching allow policy,
// the recomputation enforces the same request rules as the online
// decision: a disabled subject, an organization mismatch, a missing
// subject or resource organization or identifier, an empty action, and an
// illegal resource scope all deny, with the same reasons and precedence as
// Decide. Such a rejection uses no policies, so the recomputed decision
// reports version 0 with no matched policies; it is then compared field by
// field with the preserved original and may come back inconsistent.
func RecheckDecisionOffline(org string, records []AuditRecord, cp Checkpoint, seq int) (OfflineDecisionReview, error) {
	if org == "" {
		return OfflineDecisionReview{}, ErrMissingOrganization
	}
	// Validate the whole export first. A subject-filtered page, a fragment
	// missing the beginning, or a checkpoint that does not pin the records
	// all fail here, as does any corruption after the target.
	m, err := verifyAuditMaterial(org, records, cp)
	if err != nil {
		return OfflineDecisionReview{}, err
	}
	return recheckVerifiedOffline(m, seq)
}

// policiesBefore searches records[:limit] for the policy change record that
// published version and returns a detached copy of its full content. The
// gapless chain validation guarantees records are in sequence order.
func policiesBefore(records []AuditRecord, limit, version int) ([]Policy, bool) {
	for i := 0; i < limit; i++ {
		r := &records[i]
		if r.Kind != AuditPolicyChange || r.Change == nil {
			continue
		}
		if r.Change.Version == version {
			return append([]Policy(nil), r.Change.Policies...), true
		}
	}
	return nil, false
}

// cloneDecisionValue returns a decision detached from the input's matched
// slice. The list is detached whenever it is non-nil, including a non-nil
// empty list that still has spare capacity, so an append by one receiver
// can never reach another copy.
func cloneDecisionValue(d Decision) Decision {
	d.Matched = cloneStrings(d.Matched)
	return d
}

// decisionsEqual compares every decision field. A nil matched list and an
// empty matched list describe the same set of hits.
func decisionsEqual(a, b Decision) bool {
	if a.Allowed != b.Allowed || a.Reason != b.Reason || a.Version != b.Version {
		return false
	}
	if len(a.Matched) == 0 && len(b.Matched) == 0 {
		return true
	}
	if len(a.Matched) != len(b.Matched) {
		return false
	}
	for i := range a.Matched {
		if a.Matched[i] != b.Matched[i] {
			return false
		}
	}
	return true
}

// verifyAuditObserver, when non-nil, is invoked once for every complete
// VerifyAudit chain validation performed by this package. It exists so
// tests can pin the review flow to a single chain pass per invocation:
// decode and review must share one verification, never validate the same
// material twice. It is a test seam, not production behavior — it is nil in
// normal use and observes nothing about validation's result.
var verifyAuditObserver func()

// SetVerifyAuditObserverForTesting installs observe as the chain-validation
// observer: it is invoked once for every complete VerifyAudit pass the
// package performs. The returned function restores the previous observer
// (the normal nil observer). It exists only so tests can pin the offline
// review flow to one chain validation per command invocation; it has no
// effect on validation itself or on any result.
func SetVerifyAuditObserverForTesting(observe func()) (restore func()) {
	prev := verifyAuditObserver
	verifyAuditObserver = observe
	return func() { verifyAuditObserver = prev }
}

