278			t.Helper()
279			rs := cloneExportedRecords(recs)
280			rs = mutate(rs)
281			b, err := EncodeAuditArchive("acme", rs, checkpoint)
282			if !errors.Is(err, ErrInvalidRange) || b != nil {
283				t.Fatalf("encode bad material: bytes=%v err=%v, want ErrInvalidRange", b, err)
284			}
285		}
286		bad(func(r []AuditRecord) []AuditRecord { return r[1:] }, cp)                       // missing beginning
287		bad(func(r []AuditRecord) []AuditRecord { return r[:2] }, cp)                       // checkpoint past material
288		bad(func(r []AuditRecord) []AuditRecord { r[0], r[1] = r[1], r[0]; return r }, cp)  // reordered
289		bad(func(r []AuditRecord) []AuditRecord { r[2].Change.Version = 99; return r }, cp) // later record changed
290		bad(func(r []AuditRecord) []AuditRecord { return r },
291			Checkpoint{Org: "acme", EndSeq: cp.EndSeq, Fingerprint: cp.Fingerprint + "x"}) // bad checkpoint
292		bad(func(r []AuditRecord) []AuditRecord { return r },
293			Checkpoint{Org: "globex", EndSeq: cp.EndSeq, Fingerprint: cp.Fingerprint}) // foreign checkpoint org
294	
295		// A record from another organization, even fingerprint-correct for it.
296		foreign := syntheticRecord("globex", 1, AuditDecision, nil, &DecisionRecord{
297			Request:  request("globex", "u1", "r1", "org/a", "read"),
298			Decision: Decision{Allowed: false, Version: 0},
299		}, genesisFingerprint("globex"))
300		mixed := cloneExportedRecords(recs)
301		mixed[2] = foreign
302		if b, err := EncodeAuditArchive("acme", mixed, cp); !errors.Is(err, ErrInvalidRange) || b != nil {
303			t.Fatalf("foreign record encode: bytes=%v err=%v", b, err)
304		}
305	
306		// A well-fingerprinted record whose payload does not match its kind.
307		wrongPayload := syntheticRecord("acme", 1, AuditDecision, &PolicyChange{Version: 1}, nil, genesisFingerprint("acme"))
308		if b, err := EncodeAuditArchive("acme", []AuditRecord{wrongPayload},
309			Checkpoint{Org: "acme", EndSeq: 1, Fingerprint: wrongPayload.Fingerprint}); !errors.Is(err, ErrInvalidRange) || b != nil {
310			t.Fatalf("payload/kind mismatch: bytes=%v err=%v", b, err)
311		}
312	}
