333	// TestArchiveDecodeFramingErrors covers every framing failure mode.
334	func TestArchiveDecodeFramingErrors(t *testing.T) {
335		s := NewStore()
336		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
337		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
338		recs, cp, err := s.AuditExport("acme", 0)
339		if err != nil {
340			t.Fatal(err)
341		}
342		good, err := EncodeAuditArchive("acme", recs, cp)
343		if err != nil {
344			t.Fatal(err)
345		}
346	
347		mustFail := func(name string, data []byte) {
348			t.Helper()
349			got, err := DecodeAuditArchive(data, "acme", cp)
350			if !errors.Is(err, ErrInvalidArchive) || got != nil {
351				t.Fatalf("%s: records=%v err=%v, want ErrInvalidArchive and no records", name, got, err)
352			}
353		}
354		mustFail("nil", nil)
355		mustFail("empty", []byte{})
356		mustFail("garbage", []byte("this is certainly not an audit archive"))
357		mustFail("almost magic", append([]byte(archiveMagic[:len(archiveMagic)-1]), 'x'))
358		// Truncations at every boundary class.
359		for _, cut := range []int{1, 4, 31, 32, 33, len(archiveMagic), len(archiveMagic) + 1, len(good) - 1} {
360			if cut < len(good) {
361				mustFail(fmt.Sprintf("truncated %d", cut), good[:cut])
362			}
363		}
364		// Flip a byte in the magic.
365		flip := append([]byte(nil), good...)
366		flip[0] ^= 0x80
367		mustFail("bad magic", flip)
368		// Declared length beyond the actual file.
369		tooLong := append([]byte(nil), good...)
370		binary.BigEndian.PutUint32(tooLong[len(archiveMagic):], binary.BigEndian.Uint32(tooLong[len(archiveMagic):])+100)
371		mustFail("declared length too large", tooLong)
372		// Declared length shorter: bytes of the good frame become trailing.
373		tooShort := append([]byte(nil), good...)
374		binary.BigEndian.PutUint32(tooShort[len(archiveMagic):], binary.BigEndian.Uint32(tooShort[len(archiveMagic):])-1)
375		mustFail("declared length too small", tooShort)
376		// Damage inside the payload with the original checksum left intact.
377		damaged := append([]byte(nil), good...)
378		damaged[len(archiveMagic)+5] ^= 0x01
379		mustFail("payload bitflip, stale checksum", damaged)
380		// Damage inside the checksum.
381		csumDamage := append([]byte(nil), good...)
382		csumDamage[len(csumDamage)-1] ^= 0x01
383		mustFail("checksum bitflip", csumDamage)
384		// A second full archive concatenated to the first is trailing material.
385		mustFail("concatenated second archive", append(append([]byte(nil), good...), good...))
386		// Ordinary trailing junk.
387		mustFail("trailing junk", append(append([]byte(nil), good...), 0, 1, 2, 3))
388	
389		// A content change with a recomputed checksum passes framing but must
390		// fail chain validation with ErrInvalidRange.
391		tampered := reframe(t, good, func(payload []byte) []byte {
392			idx := bytes.Index(payload, []byte("matched allow policy"))
393			if idx < 0 {
394				t.Fatal("fixture reason not found in payload")
395			}
396			payload[idx] ^= 0x01 // same length, no length prefix or marker moves
397			return payload
398		})
399		if got, err := DecodeAuditArchive(tampered, "acme", cp); !errors.Is(err, ErrInvalidRange) || got != nil {
400			t.Fatalf("checksum-valid tampered content: records=%v err=%v, want ErrInvalidRange", got, err)
401		}
402	}
