466	// TestArchiveCheckpointInsideIsNotAuthority proves a file that internally
467	// carries one checkpoint still validates exclusively against the caller's.
468	func TestArchiveCheckpointInsideIsNotAuthority(t *testing.T) {
469		s := NewStore()
470		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
471		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
