771				}
772			})
773		}
774	
775		// The same envelope denial, correctly recorded with version 0 and no
776		// matches, is consistent even though the record names no version.
777		t.Run("correctly recorded denial", func(t *testing.T) {
778			recs, cp := syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
779				func(seq int) (string, *PolicyChange, *DecisionRecord) {
780					return AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{
781						{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
782					}}, nil
783				},
784				func(seq int) (string, *PolicyChange, *DecisionRecord) {
785					return AuditDecision, nil, &DecisionRecord{
786						Request:  req,
787						Decision: Decision{Allowed: false, Reason: "subject is disabled"},
788					}
789				},
790			})
791			got, err := RecheckDecisionOffline(org, recs, cp, 2)
792			if err != nil {
793				t.Fatalf("review: %v", err)
794			}
795			if !got.Consistent {
796				t.Fatalf("correctly recorded envelope denial must be consistent: %+v", got)
797			}
798		})
799	}
