801	// TestOfflineReviewBadRequestDoesNotMaskMissingVersion ensures the version
802	// lookup still wins when the declared version is absent (or only after the
803	// target), even if the request itself would be rejected by the envelope.
804	func TestOfflineReviewBadRequestDoesNotMaskMissingVersion(t *testing.T) {
