// invalidScopeReviews enumerate resource scopes the envelope must reject
// even when a non-zero version exists.
func invalidScopeReviews() map[string]string {
	return map[string]string{
		"empty path":          "",
		"leading slash":       "/org/a",
		"trailing slash":      "org/a/",
		"consecutive slashes": "org//a",
		"dot segment":         "org/./a",
		"dotdot segment":      "org/../a",
	}
}

// offlineBadRequest returns a request that fails exactly one envelope
// condition when reviewed for org, together with the online reason.
func offlineBadRequestCases(org string) map[string]struct {
	modify func(OrgRequest) OrgRequest
	reason string
} {
	return map[string]struct {
		modify func(OrgRequest) OrgRequest
		reason string
	}{
		"disabled subject": {
			modify: func(r OrgRequest) OrgRequest { r.Subject.Disabled = true; return r },
			reason: "subject is disabled",
		},
		"missing subject organization": {
			modify: func(r OrgRequest) OrgRequest { r.SubjectOrg = ""; return r },
			reason: "missing subject organization",
		},
		"missing resource organization": {
			modify: func(r OrgRequest) OrgRequest { r.ResourceOrg = ""; return r },
			reason: "missing resource organization",
		},
		"subject organization mismatch": {
			modify: func(r OrgRequest) OrgRequest { r.SubjectOrg = "globex"; return r },
			reason: "organization mismatch",
		},
		"resource organization mismatch": {
			modify: func(r OrgRequest) OrgRequest { r.ResourceOrg = "globex"; return r },
			reason: "organization mismatch",
		},
		"missing subject id": {
			modify: func(r OrgRequest) OrgRequest { r.Subject.ID = ""; return r },
			reason: "missing subject id",
		},
		"missing resource id": {
			modify: func(r OrgRequest) OrgRequest { r.Resource.ID = ""; return r },
			reason: "missing resource id",
		},
		"missing action": {
			modify: func(r OrgRequest) OrgRequest { r.Action = ""; return r },
			reason: "missing action",
		},
	}
}

// offlineForgedAllowChain builds a chain-valid export: version 1 carries a
// fully matching allow policy (optionally resource-restricted), and the
// target decision names version 1 and claims to be allowed by it.
func offlineForgedAllowChain(t *testing.T, org string, req OrgRequest, resourceID string) ([]AuditRecord, Checkpoint) {
	t.Helper()
	p := Policy{ID: "p1", Subject: req.Subject.ID, Action: req.Action, Scope: "org/a", Effect: EffectAllow, ResourceID: resourceID}
	return syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{p}}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  req,
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
			}
		},
	})
}

// TestOfflineReviewEnforcesRequestRulesAtNonZeroVersion proves the audit
// fingerprint cannot substitute for evaluating the request: a record that
// names an existing non-zero version with a matching allow policy must
// still recompute to the same envelope denial the online decision gives.
func TestOfflineReviewEnforcesRequestRulesAtNonZeroVersion(t *testing.T) {
	const org = "acme"
	for name, tc := range offlineBadRequestCases(org) {
		t.Run(name, func(t *testing.T) {
			req := tc.modify(request(org, "u1", "r1", "org/a", "read"))
			recs, cp := offlineForgedAllowChain(t, org, req, "")
			got, err := RecheckDecisionOffline(org, recs, cp, 2)
			if err != nil {
				t.Fatalf("request denial is a result, not an error: %v", err)
			}
			if got.Consistent {
				t.Fatalf("original allow must not match the recomputed denial: %+v", got)
			}
			if !got.Original.Allowed || got.Original.Version != 1 {
				t.Fatalf("original claim not preserved: %+v", got.Original)
			}
			if got.Recomputed.Allowed || got.Recomputed.Reason != tc.reason {
				t.Fatalf("recomputed = %+v, want denial %q", got.Recomputed, tc.reason)
			}
			if got.Recomputed.Version != 0 {
				t.Fatalf("envelope rejection used no version, got %d", got.Recomputed.Version)
			}
			if len(got.Recomputed.Matched) != 0 {
				t.Fatalf("envelope rejection matched no policies, got %v", got.Recomputed.Matched)
			}
		})
	}

	t.Run("invalid scope forms", func(t *testing.T) {
		for name, scope := range invalidScopeReviews() {
			t.Run(name, func(t *testing.T) {
				req := request(org, "u1", "r1", scope, "read")
				recs, cp := offlineForgedAllowChain(t, org, req, "")
				got, err := RecheckDecisionOffline(org, recs, cp, 2)
				if err != nil {
					t.Fatalf("invalid scope is a result, not an error: %v", err)
				}
				if got.Consistent || got.Recomputed.Allowed ||
					got.Recomputed.Version != 0 || len(got.Recomputed.Matched) != 0 {
					t.Fatalf("invalid scope %q review = %+v", scope, got)
				}
				if want := "invalid scope: "; got.Recomputed.Reason == want ||
					len(got.Recomputed.Reason) <= len(want) ||
					got.Recomputed.Reason[:len(want)] != want {
					t.Fatalf("reason = %q, want an invalid-scope denial", got.Recomputed.Reason)
				}
			})
		}
	})

	t.Run("resource restricted matching policy", func(t *testing.T) {
		// Even a policy matching subject, action, scope and the exact
		// resource must not bypass the envelope conditions.
		req := request(org, "u1", "r1", "org/a", "read")
		req.Subject.Disabled = true
		recs, cp := offlineForgedAllowChain(t, org, req, "r1")
		got, err := RecheckDecisionOffline(org, recs, cp, 2)
		if err != nil {
			t.Fatalf("review: %v", err)
		}
		if got.Consistent || got.Recomputed.Allowed ||
			got.Recomputed.Reason != "subject is disabled" ||
			got.Recomputed.Version != 0 || len(got.Recomputed.Matched) != 0 {
			t.Fatalf("resource-restricted policy bypassed envelope: %+v", got)
		}
	})
}

// TestOfflineReviewRecomputedReasonPrecedenceMatchesOnline checks that when
// several envelope conditions fail at once, the recomputed reason and order
// match checkRequest exactly.
func TestOfflineReviewRecomputedReasonPrecedenceMatchesOnline(t *testing.T) {
	const org = "acme"
	// Empty subject org precedes empty resource org precedes missing ids
	// precedes missing action; mismatches follow the missing-field block;
	// invalid scope precedes the disabled check.
	type precedenceCase struct {
		modify func(OrgRequest) OrgRequest
		reason string
	}
	cases := []precedenceCase{
		{func(r OrgRequest) OrgRequest {
			r.SubjectOrg = ""
			r.ResourceOrg = ""
			r.Subject.ID = ""
			r.Resource.ID = ""
			r.Action = ""
			r.Subject.Disabled = true
			return r
		}, "missing subject organization"},
		{func(r OrgRequest) OrgRequest {
			r.SubjectOrg = "globex"
			r.ResourceOrg = "other"
			r.Action = ""
			return r
		}, "missing action"},
		{func(r OrgRequest) OrgRequest {
			r.SubjectOrg = "globex"
			r.ResourceOrg = "other"
			r.Resource.Scope = "org/../a"
			r.Subject.Disabled = true
			return r
		}, "organization mismatch"},
		{func(r OrgRequest) OrgRequest {
			r.Resource.Scope = "/bad"
			r.Subject.Disabled = true
			return r
		}, "invalid scope: scope \"/bad\" has a leading or trailing slash"},
	}
	for i, tc := range cases {
		req := tc.modify(request(org, "u1", "r1", "org/a", "read"))
		// What the online path would have returned for the same request.
		online, ok := checkRequest(org, req)
		if ok {
			t.Fatalf("case %d request unexpectedly valid", i)
		}
		recs, cp := syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
			func(seq int) (string, *PolicyChange, *DecisionRecord) {
				return AuditPolicyChange, &PolicyChange{
					Version: 1,
					Policies: []Policy{{ID: "p1", Subject: req.Subject.ID, Action: req.Action,
						Scope: "org/a", Effect: EffectAllow}},
				}, nil
			},
			func(seq int) (string, *PolicyChange, *DecisionRecord) {
				return AuditDecision, nil, &DecisionRecord{
					Request:  req,
					Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
				}
			},
		})
		got, err := RecheckDecisionOffline(org, recs, cp, 2)
		if err != nil {
			t.Fatalf("case %d: %v", i, err)
		}
		if got.Consistent {
			t.Fatalf("case %d unexpectedly consistent: %+v", i, got)
		}
		if !reflect.DeepEqual(got.Recomputed, online) {
			t.Fatalf("case %d recomputed = %+v, want online envelope decision %+v", i, got.Recomputed, online)
		}
		if got.Recomputed.Reason != tc.reason {
			t.Fatalf("case %d reason = %q, want %q", i, got.Recomputed.Reason, tc.reason)
		}
	}
}

// TestOfflineReviewOriginalDenyStillInconsistent covers a record that does
// deny, but records the wrong version, reason or matched list relative to
// the recomputed envelope denial.
func TestOfflineReviewOriginalDenyStillInconsistent(t *testing.T) {
	const org = "acme"
	req := request(org, "u1", "r1", "org/a", "read")
	req.Subject.Disabled = true

	variants := map[string]Decision{
		"wrong version": {Allowed: false, Reason: "subject is disabled", Matched: nil, Version: 1},
		"wrong reason":  {Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1},
		"wrong matched": {Allowed: false, Reason: "subject is disabled", Matched: []string{"p1"}, Version: 1},
		"allowed claim": {Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
	}
	for name, claim := range variants {
		t.Run(name, func(t *testing.T) {
			recs, cp := syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
				func(seq int) (string, *PolicyChange, *DecisionRecord) {
					return AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{
						{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
					}}, nil
				},
				func(seq int) (string, *PolicyChange, *DecisionRecord) {
					return AuditDecision, nil, &DecisionRecord{Request: req, Decision: claim}
				},
			})
			got, err := RecheckDecisionOffline(org, recs, cp, 2)
			if err != nil {
				t.Fatalf("review: %v", err)
			}
			if got.Consistent {
				t.Fatalf("%s must be inconsistent: %+v", name, got)
			}
			if !decisionsEqual(got.Original, claim) {
				t.Fatalf("original altered: %+v want %+v", got.Original, claim)
			}
			want := Decision{Allowed: false, Reason: "subject is disabled"}
			if !decisionsEqual(got.Recomputed, want) {
				t.Fatalf("recomputed = %+v, want %+v", got.Recomputed, want)
			}
		})
	}

	// The same envelope denial, correctly recorded with version 0 and no
	// matches, is consistent even though the record names no version.
	t.Run("correctly recorded denial", func(t *testing.T) {
		recs, cp := syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
			func(seq int) (string, *PolicyChange, *DecisionRecord) {
				return AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{
					{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow},
				}}, nil
			},
			func(seq int) (string, *PolicyChange, *DecisionRecord) {
				return AuditDecision, nil, &DecisionRecord{
					Request:  req,
					Decision: Decision{Allowed: false, Reason: "subject is disabled"},
				}
			},
		})
		got, err := RecheckDecisionOffline(org, recs, cp, 2)
		if err != nil {
			t.Fatalf("review: %v", err)
		}
		if !got.Consistent {
			t.Fatalf("correctly recorded envelope denial must be consistent: %+v", got)
		}
	})
}

// TestOfflineReviewBadRequestDoesNotMaskMissingVersion ensures the version
// lookup still wins when the declared version is absent (or only after the
// target), even if the request itself would be rejected by the envelope.
func TestOfflineReviewBadRequestDoesNotMaskMissingVersion(t *testing.T) {
	const org = "acme"
	legal := request(org, "u1", "r1", "org/a", "read")
	bad := request(org, "u1", "r1", "org/a", "read")
	bad.Subject.Disabled = true
	bad.SubjectOrg = "globex"

	// Version named by the decision appears nowhere in the export.
	missingRecs, missingCP := syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  bad,
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 5},
			}
		},
	})
	if _, err := RecheckDecisionOffline(org, missingRecs, missingCP, 1); !errors.Is(err, ErrVersionNotFound) {
		t.Fatalf("missing version masked by bad request: %v", err)
	}

	// Version present only after the target: still ErrVersionNotFound.
	laterRecs, laterCP := syntheticChain(org, []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  bad,
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 2},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version: 2,
				Policies: []Policy{{ID: "p1", Subject: legal.Subject.ID, Action: legal.Action,
					Scope: "org/a", Effect: EffectAllow}},
			}, nil
		},
	})
	if _, err := RecheckDecisionOffline(org, laterRecs, laterCP, 1); !errors.Is(err, ErrVersionNotFound) {
		t.Fatalf("later-only version masked by bad request: %v", err)
	}
}

// This file pins down the decoder's handling of a corrupted decision
// *reason string length*: archives whose outer framing, declared payload
// length and checksum are all correct, but where one decision's Reason
// length word promises bytes the payload does not contain, or where that
// length word itself is only partly saved. The reason is an ordinary
// length-prefixed stringField in the wire format, so this protection is the
// generic string boundary read — but a decision reason is the field an
// auditor actually reads, and it had no regression of its own the way the
// internal list counts and the single-byte markers do.
//
// Two failure classes must stay distinct. A reason length that cannot be
// satisfied by the remaining material makes the archive unreadable: the
// read must fail with ErrInvalidArchive (matched by errors.Is), never
// panic, never provision the declared (up to 4294967295) byte count, and
// never treat the missing tail as an empty reason and continue. Flipping a
// byte inside reason *content* while leaving every length and marker legal
// instead keeps the structure readable and fails as content against the
// original fingerprints and retained checkpoint: ErrInvalidRange, never
// ErrInvalidArchive.
//
// As with the list- and marker-corruption files, every structural corruption
// below is reframed with a consistent outer length and checksum. That
// forces the observed failure to come from being unable to read the reason
// completely, not from the framing-level checksum check.
package darksafe

import (
	"bytes"
	"encoding/binary"
	"errors"
	"reflect"
	"runtime"
	"strings"
	"testing"
)

// locateReasonLengthWord returns the payload offset of the 4-byte length
// word that prefixes reason's content bytes. The reason content must occur
// exactly once, so the length word immediately before it is unambiguous; a
// format or fixture change that breaks this fails loudly instead of
// corrupting the wrong field.
func locateReasonLengthWord(t *testing.T, payload []byte, reason string) int {
	t.Helper()
	needle := []byte(reason)
	idx := bytes.Index(payload, needle)
	if idx < 4 {
		t.Fatalf("decision reason %q not found in payload", reason)
	}
	if bytes.Index(payload[idx+1:], needle) >= 0 {
		t.Fatalf("decision reason %q must be unique for an unambiguous locate", reason)
	}
	return idx - 4
}

// reasonChainFixture builds complete, valid material: one policy publish
// followed by one decision carrying the unique, non-empty laterReason. It
// returns the encoded archive, the caller's retained checkpoint and the
// reason text the tests corrupt.
func reasonChainFixture(t *testing.T, laterReason string) ([]byte, Checkpoint) {
	t.Helper()
	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version:  1,
				Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: true, Reason: laterReason, Matched: []string{"p1"}, Version: 1},
			}
		},
	})
	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode reason fixture: %v", err)
	}
	return archive, cp
}

// TestArchiveDecisionReasonLengthCorruption covers the shapes that make a
// decision reason unreadable while the outer length and checksum still
// hold: a declared reason length larger than the bytes left (by one and by
// a wide margin), the maximum uint32 length on a body that could never hold
// it, and a length word physically cut off partway. Each must fail as
// ErrInvalidArchive with nil records — not ErrInvalidRange, not a crash,
// not a phantom allocation, and not an empty-reason continuation — and must
// leave both the archive bytes and the retained checkpoint untouched.
func TestArchiveDecisionReasonLengthCorruption(t *testing.T) {
	reason := "the-decision-reason-b7d2"
	good, cp := reasonChainFixture(t, reason)
	basePayload := payloadOf(t, good)
	lenAt := locateReasonLengthWord(t, basePayload, reason)
	if got := binary.BigEndian.Uint32(basePayload[lenAt:]); got != uint32(len(reason)) {
		t.Fatalf("located length word = %d, want %d", got, len(reason))
	}

	// expectInvalid runs one payload mutation, reframes it with a consistent
	// outer length and checksum, and asserts the whole read fails as an
	// unreadable archive without delivering records or rewriting inputs.
	expectInvalid := func(name, wantSubstr string, mutate func(p []byte) []byte) {
		t.Helper()
		payload := mutate(append([]byte(nil), basePayload...))
		data := framePayload(payload)
		dataSnapshot := append([]byte(nil), data...)
		cpSnapshot := cp

		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidArchive) {
			t.Fatalf("%s: err = %v, want ErrInvalidArchive", name, err)
		}
		if errors.Is(err, ErrInvalidRange) {
			t.Fatalf("%s: an unreadable reason counted as a content error: %v", name, err)
		}
		if got != nil {
			t.Fatalf("%s: returned %d records on a damaged reason, want nil", name, len(got))
		}
		if wantSubstr != "" && !strings.Contains(err.Error(), wantSubstr) {
			t.Fatalf("%s: err = %q, want substring %q", name, err.Error(), wantSubstr)
		}
		if !bytes.Equal(data, dataSnapshot) {
			t.Fatalf("%s: failed decode rewrote the archive bytes", name)
		}
		if cp != cpSnapshot {
			t.Fatalf("%s: failed decode rewrote the retained checkpoint", name)
		}
	}

	// Bytes left after the reason length word, which a complete reason plus
	// the matched list, version and two fingerprints would occupy.
	remaining := len(basePayload) - (lenAt + 4)

	// The length word is intact but promises more reason bytes than remain.
	// The payload itself keeps its length, so the only thing wrong is that
	// the reason cannot be read in full: the error must originate at that
	// string boundary, not at the (recomputed, valid) checksum.
	expectInvalid("reason length exceeds remaining by one", "truncated archive payload",
		func(p []byte) []byte {
			binary.BigEndian.PutUint32(p[lenAt:], uint32(remaining+1))
			return p
		})
	expectInvalid("reason length far exceeds remaining", "truncated archive payload",
		func(p []byte) []byte {
			binary.BigEndian.PutUint32(p[lenAt:], uint32(remaining)+1_000_000)
			return p
		})

	// 4294967295 reason bytes on this small body must be rejected on the
	// remaining-byte bound, without enumerating or provisioning the phantom
	// bytes. Measure the error path: a regression that trusted the length
	// would try to allocate gigabytes here.
	measureHuge := func(name string, mutate func(p []byte) []byte) {
		t.Helper()
		payload := mutate(append([]byte(nil), basePayload...))
		data := framePayload(payload)
		var before, after runtime.MemStats
		runtime.GC()
		runtime.ReadMemStats(&before)
		got, err := DecodeAuditArchive(data, "acme", cp)
		runtime.ReadMemStats(&after)
		if !errors.Is(err, ErrInvalidArchive) || got != nil {
			t.Fatalf("%s: records=%v err=%v, want ErrInvalidArchive, nil", name, got, err)
		}
		if !strings.Contains(err.Error(), "truncated archive payload") {
			t.Fatalf("%s: err = %q, want the reason read-boundary rejection", name, err.Error())
		}
		if alloc := after.TotalAlloc - before.TotalAlloc; alloc > 16<<20 {
			t.Fatalf("%s allocated %d bytes, want a small error path", name, alloc)
		}
	}
	measureHuge("max uint32 reason length on small body",
		func(p []byte) []byte {
			binary.BigEndian.PutUint32(p[lenAt:], 0xffffffff)
			return p
		})

	// The length word is only partly saved: cut the payload 0..3 bytes into
	// the word (and beyond, for the fully-missing end) and reframe. The
	// reader cannot even learn the declared length, so each cut must be a
	// truncation error rather than a zero/empty reason.
	for _, cutIntoWord := range []int{0, 1, 2, 3} {
		name := "reason length word cut with " + string(rune('0'+cutIntoWord)) + " of 4 bytes present"
		expectInvalid(name, "truncated archive payload",
			func(p []byte) []byte { return p[:lenAt+cutIntoWord] })
	}
}

// TestArchiveTinyReasonHugeLengthNoAllocation is the dedicated emphasis of
// the allocation requirement: a hand-built, tiny archive that reaches a
// decision and then declares its reason to be 4294967295 bytes long with no
// bytes following. Decode must return ErrInvalidArchive promptly, without
// crashing or provisioning as if the declared length were real.
func TestArchiveTinyReasonHugeLengthNoAllocation(t *testing.T) {
	w := &archiveWriter{}
	w.stringField("acme")
	w.u32(1)
	w.stringField("g")
	w.u32(1) // one record
	w.stringField("acme")
	w.u32(1) // sequence
	w.stringField(AuditDecision)
	w.raw(nilMarker())               // change absent
	w.raw([]byte{archiveTagPresent}) // decision present
	w.stringField("acme")            // request SubjectOrg
	w.stringField("acme")            // request ResourceOrg
	w.stringField("u1")              // subject ID
	w.stringField("user")            // subject kind
	w.raw(nilMarker())               // roles nil
	w.boolean(false)                 // subject disabled
	w.stringField("r1")              // resource ID
	w.stringField("org/a")           // resource scope
	w.stringField("read")            // action
	w.boolean(true)                  // decision allowed
	w.u32(0xffffffff)                // decision reason length: 4294967295, no bytes follow
	if w.err != nil {
		t.Fatal(w.err)
	}
	// The record-count floor (22 bytes per record) must still pass, proving
	// the reader actually reaches the reason length rather than rejecting the
	// record count first.
	if len(w.buf) < 22 {
		t.Fatalf("tiny body %d bytes too short to reach the reason field", len(w.buf))
	}
	data := framePayload(w.buf)

	var before, after runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&before)
	got, err := DecodeAuditArchive(data, "acme",
		Checkpoint{Org: "acme", EndSeq: 1, Fingerprint: "g"})
	runtime.ReadMemStats(&after)
	if !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("tiny archive with huge reason length: records=%v err=%v, want ErrInvalidArchive, nil", got, err)
	}
	if !strings.Contains(err.Error(), "truncated archive payload") {
		t.Fatalf("tiny archive err = %q, want the reason read-boundary rejection", err.Error())
	}
	if alloc := after.TotalAlloc - before.TotalAlloc; alloc > 16<<20 {
		t.Fatalf("huge declared reason length allocated %d bytes, want a small error path", alloc)
	}
}

// TestArchiveLaterRecordReasonDamageDiscardsPrefix is the all-or-nothing
// boundary the requirement names: a complete policy publish and a normal,
// reviewable decision precede a later decision whose reason length is
// corrupt. The auditor's review target sits entirely in the intact part.
// The whole read must still fail and must never first hand back the intact
// records, so the earlier target cannot be reviewed out of the damaged
// material.
func TestArchiveLaterRecordReasonDamageDiscardsPrefix(t *testing.T) {
	targetReason := "matched allow policy"
	laterReason := "later-decision-reason-5e81"
	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version:  1,
				Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			// The decision the auditor intends to review, before the damage.
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: true, Reason: targetReason, Matched: []string{"p1"}, Version: 1},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u2", "r1", "org/a", "read"),
				Decision: Decision{Allowed: false, Reason: laterReason, Version: 1},
			}
		},
	})
	good, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}

	// The intact prefix (publish + review target) really is usable on its
	// own, so a nil result for the full archive can only mean it was
	// deliberately withheld rather than merely unread.
	prefixCP := Checkpoint{Org: "acme", EndSeq: 2, Fingerprint: recs[1].Fingerprint}
	prefixArchive, err := EncodeAuditArchive("acme", recs[:2], prefixCP)
	if err != nil {
		t.Fatalf("encode prefix: %v", err)
	}
	prefix, err := DecodeAuditArchive(prefixArchive, "acme", prefixCP)
	if err != nil || len(prefix) != 2 {
		t.Fatalf("intact prefix must decode: %d records, %v", len(prefix), err)
	}
	if review, err := RecheckDecisionOffline("acme", prefix, prefixCP, 2); err != nil || !review.Consistent {
		t.Fatalf("intact prefix target must review: %+v, %v", review, err)
	}

	basePayload := payloadOf(t, good)
	lenAt := locateReasonLengthWord(t, basePayload, laterReason)
	remaining := len(basePayload) - (lenAt + 4)

	corrupt := func(name string, mutate func(p []byte) []byte) {
		t.Helper()
		payload := mutate(append([]byte(nil), basePayload...))
		data := framePayload(payload)
		dataSnapshot := append([]byte(nil), data...)
		cpSnapshot := cp

		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidArchive) || got != nil {
			t.Fatalf("%s: records=%v err=%v, want ErrInvalidArchive, nil", name, got, err)
		}
		if !bytes.Equal(data, dataSnapshot) || cp != cpSnapshot {
			t.Fatalf("%s: failed decode rewrote its inputs", name)
		}
	}
	// Both a one-byte overrun and the maximum declared length in the later
	// record sink the entire read, target record included.
	corrupt("later reason exceeds remaining by one", func(p []byte) []byte {
		binary.BigEndian.PutUint32(p[lenAt:], uint32(remaining+1))
		return p
	})
	corrupt("later reason declares max uint32", func(p []byte) []byte {
		binary.BigEndian.PutUint32(p[lenAt:], 0xffffffff)
		return p
	})
	corrupt("later reason length word cut mid-read", func(p []byte) []byte {
		return p[:lenAt+2]
	})
}

// TestArchiveReasonContentChangeIsNotArchiveDamage keeps format damage
// separate from untrusted content at the reason field: flip one byte inside
// the reason text, past its length word, leaving the declared length, every
// marker and the whole structure legal, and recompute the outer checksum.
// The archive is fully readable, so against the unchanged original
// fingerprints and independently retained checkpoint it must fail as
// ErrInvalidRange — not be swept into ErrInvalidArchive.
func TestArchiveReasonContentChangeIsNotArchiveDamage(t *testing.T) {
	reason := "the-decision-reason-b7d2"
	good, cp := reasonChainFixture(t, reason)

	tampered := reframe(t, good, func(payload []byte) []byte {
		at := locateReasonLengthWord(t, payload, reason) + 4 // first content byte
		payload[at] ^= 0x01                                  // same length, length word untouched
		return payload
	})
	got, err := DecodeAuditArchive(tampered, "acme", cp)
	if !errors.Is(err, ErrInvalidRange) || got != nil {
		t.Fatalf("readable-format reason content change: records=%v err=%v, want ErrInvalidRange, nil", got, err)
	}
	if errors.Is(err, ErrInvalidArchive) {
		t.Fatal("a legal-length reason byte flip must not be reported as archive-format damage")
	}
}

// TestArchiveValidReasonsRoundTrip locks the legal behavior the corruption
// guard must not disturb: reasons are restored from their exact bytes with
// length understood in bytes. Chinese, spaces, control characters, a lone
// non-UTF-8 byte and a genuine U+FFFD all survive untruncated and
// unnormalized, an empty reason stays the empty string (distinct from a
// missing field), and the material with its retained checkpoint still
// verifies and feeds offline review.
func TestArchiveValidReasonsRoundTrip(t *testing.T) {
	rawReason := " 理由 中\t\n\r\x00\x01 " + invalidByte
	emptyReason := ""
	genuineReplacement := "理" + replacementRune + "由"

	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version:  1,
				Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
			}, nil
		},
		// A canonical allow decision: the reviewable control.
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
			}
		},
		// Spaces, Chinese, control characters and a lone non-UTF-8 byte.
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u3", "r1", "org/a", "read"),
				Decision: Decision{Allowed: false, Reason: rawReason, Version: 1},
			}
		},
		// An explicitly empty reason.
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u4", "r1", "org/a", "read"),
				Decision: Decision{Allowed: false, Reason: emptyReason, Version: 1},
			}
		},
		// A genuine U+FFFD must stay distinct from the lone 0xFF above.
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u5", "r1", "org/a", "read"),
				Decision: Decision{Allowed: false, Reason: genuineReplacement, Version: 1},
			}
		},
	})

	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode valid reasons: %v", err)
	}
	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatalf("decode valid reasons: %v", err)
	}
	if !reflect.DeepEqual(got, recs) {
		t.Fatalf("valid reasons changed across the archive:\n got %+v\nwant %+v", got, recs)
	}

	// Byte-for-byte reason assertions; length is understood in bytes.
	wantReasons := []string{"matched allow policy", rawReason, emptyReason, genuineReplacement}
	for i, want := range wantReasons {
		if gotReason := got[i+1].Decision.Decision.Reason; gotReason != want {
			t.Fatalf("record %d reason = %q, want %q", i+2, gotReason, want)
		}
	}
	if got[3].Decision.Decision.Reason != "" {
		t.Fatal("empty reason must decode as the empty string, not absent or replaced")
	}
	// The raw-byte reason and the genuine-U+FFFD reason must not collapse.
	if got[2].Decision.Decision.Reason == got[4].Decision.Decision.Reason {
		t.Fatal("lone 0xFF reason and genuine U+FFFD reason collapsed together")
	}
	if !strings.Contains(got[2].Decision.Decision.Reason, invalidByte) {
		t.Fatal("non-UTF-8 reason byte was replaced or normalized")
	}

	// Fingerprints/checkpoint unchanged and the material still verifies.
	for i := range got {
		if got[i].Fingerprint != recs[i].Fingerprint {
			t.Fatalf("record %d fingerprint changed", i+1)
		}
	}
	if err := VerifyAudit("acme", got, cp); err != nil {
		t.Fatalf("decoded valid-reason material must verify: %v", err)
	}
	// The canonical decision in the same material remains offline-reviewable.
	review, err := RecheckDecisionOffline("acme", got, cp, 2)
	if err != nil || !review.Consistent || review.Original.Reason != "matched allow policy" {
		t.Fatalf("offline review after reason round trip = %+v, %v", review, err)
	}
}

// This file pins down the decoder's handling of corrupted *internal list
// lengths*: archives whose outer framing, declared payload length and
// checksum are all correct, but where a count declared inside the payload
// cannot be satisfied by the bytes that follow. Three lists carry counts:
// the material's record list, a policy change's policy list, and the string
// lists used for subject roles and matched policies.
//
// Every corruption below is reframed with a consistent outer length and
// checksum, so exercising these cases proves the protection comes from
// decoding the payload's own structure rather than from the framing-level
// samples in audit_archive_test.go. A count the body cannot satisfy, a
// count word cut off mid-read, and a complete early item followed by an
// incomplete later item are all unreadable archives: DecodeAuditArchive
// must return ErrInvalidArchive (matched by errors.Is) and nil records,
// never a prefix and never a crash or hostile allocation.
package darksafe

import (
	"bytes"
	"crypto/sha256"
	"encoding/binary"
	"errors"
	"reflect"
	"runtime"
	"strings"
	"testing"
)

// listSite locates one length-counted list inside a payload, in payload
// byte offsets. itemEnds marks the byte just past each complete item.
type listSite struct {
	markerAt int
	countAt  int // -1 when the list is encoded nil
	itemEnds []int
}

// payloadInspector walks the known-good, two-record fixture payload in
// encode order. It exists only to locate the bytes a test corrupts; it
// mirrors archiveWriter, so a format change moves these tests off their
// target rather than silently corrupting the wrong field.
type payloadInspector struct {
	b   []byte
	pos int
}

func (c *payloadInspector) u32() int {
	v := int(binary.BigEndian.Uint32(c.b[c.pos : c.pos+4]))
	c.pos += 4
	return v
}

func (c *payloadInspector) str() {
	n := c.u32()
	c.pos += n
}

func (c *payloadInspector) marker() byte {
	m := c.b[c.pos]
	c.pos++
	return m
}

func (c *payloadInspector) stringListSite() listSite {
	s := listSite{markerAt: c.pos, countAt: -1}
	if c.marker() == archiveTagNil {
		return s
	}
	s.countAt = c.pos
	n := c.u32()
	s.itemEnds = make([]int, 0, n)
	for i := 0; i < n; i++ {
		c.str()
		s.itemEnds = append(s.itemEnds, c.pos)
	}
	return s
}

func (c *payloadInspector) policySite() {
	c.str() // ID
	c.str() // Subject
	c.str() // Action
	c.str() // Scope
	c.str() // Effect
	c.pos++ // Recursive bool
	c.str() // ResourceID
}

func (c *payloadInspector) policyListSite() listSite {
	s := listSite{markerAt: c.pos, countAt: -1}
	if c.marker() == archiveTagNil {
		return s
	}
	s.countAt = c.pos
	n := c.u32()
	s.itemEnds = make([]int, 0, n)
	for i := 0; i < n; i++ {
		c.policySite()
		s.itemEnds = append(s.itemEnds, c.pos)
	}
	return s
}

// inspectTwoRecordPayload locates the four counted lists in the fixture
// built by listCorruptionFixture.
func inspectTwoRecordPayload(t *testing.T, p []byte) fixtureSites {
	t.Helper()
	c := &payloadInspector{b: p}
	c.str()    // embedded org
	c.pos += 4 // embedded end sequence
	c.str()    // embedded checkpoint fingerprint
	records := listSite{countAt: c.pos}
	n := c.u32() // record count
	if n != 2 {
		t.Fatalf("fixture record count = %d, want 2", n)
	}

	// Record 1: policy change with two policies, absent decision.
	c.str()    // org
	c.pos += 4 // seq
	c.str()    // kind
	if m := c.marker(); m != archiveTagPresent {
		t.Fatalf("record 1 change marker = %d, want present", m)
	}
	c.pos += 4 // change version
	policies := c.policyListSite()
	c.pos += 4 // source version
	c.pos++    // rolled back bool
	if m := c.marker(); m != archiveTagNil {
		t.Fatalf("record 1 decision marker = %d, want nil", m)
	}
	c.str() // prev fingerprint
	c.str() // own fingerprint
	records.itemEnds = append(records.itemEnds, c.pos)

	// Record 2: decision with two roles and two matched policies.
	c.str()    // org
	c.pos += 4 // seq
	c.str()    // kind
	if m := c.marker(); m != archiveTagNil {
		t.Fatalf("record 2 change marker = %d, want nil", m)
	}
	if m := c.marker(); m != archiveTagPresent {
		t.Fatalf("record 2 decision marker = %d, want present", m)
	}
	c.str() // request SubjectOrg
	c.str() // request ResourceOrg
	c.str() // subject ID
	c.str() // subject Kind
	roles := c.stringListSite()
	c.pos++ // subject disabled bool
	c.str() // resource ID
	c.str() // resource scope
	c.str() // action
	c.pos++ // decision allowed bool
	c.str() // decision reason
	matched := c.stringListSite()
	c.pos += 4 // decision version
	c.str()    // prev fingerprint
	c.str()    // own fingerprint
	records.itemEnds = append(records.itemEnds, c.pos)

	if c.pos != len(p) {
		t.Fatalf("inspector ended at %d, payload length %d", c.pos, len(p))
	}
	if len(roles.itemEnds) != 2 || len(matched.itemEnds) != 2 || len(policies.itemEnds) != 2 {
		t.Fatalf("fixture lists must each hold 2 items: policies=%d roles=%d matched=%d",
			len(policies.itemEnds), len(roles.itemEnds), len(matched.itemEnds))
	}
	return fixtureSites{records: records, policies: policies, roles: roles, matched: matched}
}

// fixtureSites are the four counted lists in the two-record fixture.
type fixtureSites struct {
	records  listSite
	policies listSite
	roles    listSite
	matched  listSite
}

// framePayload wraps a (possibly corrupted) payload with correct outer
// framing, declared length and checksum, so the failure under test is
// always internal list decoding rather than framing.
func framePayload(payload []byte) []byte {
	out := append([]byte(nil), archiveMagic...)
	var lb [4]byte
	binary.BigEndian.PutUint32(lb[:], uint32(len(payload)))
	out = append(out, lb[:]...)
	out = append(out, payload...)
	sum := sha256.Sum256(payload)
	return append(out, sum[:]...)
}

// payloadOf extracts a copy of one archive's payload.
func payloadOf(t *testing.T, archive []byte) []byte {
	t.Helper()
	magicLen := len(archiveMagic)
	n := int(binary.BigEndian.Uint32(archive[magicLen : magicLen+4]))
	return append([]byte(nil), archive[magicLen+4:magicLen+4+n]...)
}

// listCorruptionFixture builds complete, valid material: one policy change
// carrying two policies followed by one decision whose subject has two
// roles and whose decision matched two policies. All four counted lists
// therefore hold real, multi-item content.
func listCorruptionFixture(t *testing.T) ([]byte, []AuditRecord, Checkpoint) {
	t.Helper()
	s := NewStore()
	s.Publish("acme", 0, []Policy{
		allowPolicy("p1", "u1", "read", "org/a", false),
		allowPolicy("p2", "u1", "read", "org/a", false),
	})
	req := OrgRequest{
		SubjectOrg:  "acme",
		ResourceOrg: "acme",
		Subject:     Subject{ID: "u1", Roles: []string{"role-a", "role-b"}},
		Resource:    Resource{ID: "r1", Scope: "org/a"},
		Action:      "read",
	}
	original := s.Decide("acme", req)
	recs, cp, err := s.AuditExport("acme", 0)
	if err != nil {
		t.Fatal(err)
	}
	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatal(err)
	}
	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatalf("fixture must decode: %v", err)
	}
	review, err := RecheckDecisionOffline("acme", got, cp, 2)
	if err != nil || !review.Consistent || !reflect.DeepEqual(review.Original, original) {
		t.Fatalf("fixture review = %+v, %v", review, err)
	}
	return archive, recs, cp
}

// TestArchiveInternalListCountCorruption covers, for every counted list,
// the shapes that make a payload unreadable: a declared count the
// remaining bytes cannot satisfy, a count word cut off mid-read, and a
// complete early item followed by a later item missing a required field.
// All arrive with valid outer framing and checksum and must be reported as
// ErrInvalidArchive with nil records — even when a complete, readable
// prefix (a full policy change and decision) precedes the damage.
func TestArchiveInternalListCountCorruption(t *testing.T) {
	good, _, cp := listCorruptionFixture(t)
	basePayload := payloadOf(t, good)
	sites := inspectTwoRecordPayload(t, basePayload)

	// expectInvalid runs one payload mutation and asserts the whole read
	// fails as an unreadable archive without delivering the intact prefix.
	// It also proves the failed call rewrites neither its input bytes nor
	// the retained checkpoint handed to it.
	expectInvalid := func(name, wantSubstr string, mutate func(p []byte) []byte) {
		t.Helper()
		payload := mutate(append([]byte(nil), basePayload...))
		data := framePayload(payload)
		dataSnapshot := append([]byte(nil), data...)
		cpSnapshot := cp

		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidArchive) {
			t.Fatalf("%s: err = %v, want ErrInvalidArchive", name, err)
		}
		if errors.Is(err, ErrInvalidRange) {
			t.Fatalf("%s: structurally unreadable list counted as a content error: %v", name, err)
		}
		if got != nil {
			t.Fatalf("%s: returned %d records on a damaged list, want nil", name, len(got))
		}
		if wantSubstr != "" && !strings.Contains(err.Error(), wantSubstr) {
			t.Fatalf("%s: err = %q, want substring %q", name, err.Error(), wantSubstr)
		}
		if !bytes.Equal(data, dataSnapshot) {
			t.Fatalf("%s: failed decode rewrote the archive bytes", name)
		}
		if cp != cpSnapshot {
			t.Fatalf("%s: failed decode rewrote the checkpoint", name)
		}
	}

	lists := []struct {
		name     string
		site     listSite
		minBytes int
	}{
		{"records", sites.records, 22},
		{"policies", sites.policies, 6*4 + 1},
		{"roles", sites.roles, 4},
		{"matched", sites.matched, 4},
	}

	for _, l := range lists {
		// A) The count word is intact but promises more items than the bytes
		// left could ever hold. Rewrite only the count (payload length
		// unchanged): the read must fail as an unreadable archive, whether
		// the per-item floor rejects the count up front or reading the
		// missing items truncates — the error class is what the caller uses.
		//
		// This count value is the smallest one whose floor exceeds the
		// remaining bytes, computed from this fixture's real offsets.
		overCount := (len(basePayload)-(l.site.countAt+4))/l.minBytes + 1
		expectInvalid(l.name+": count exceeds remaining items", "",
			func(p []byte) []byte {
				binary.BigEndian.PutUint32(p[l.site.countAt:], uint32(overCount))
				return p
			})

		// The maximum uint32 count on this small body must fail with the
		// same deterministic error for every counted list, not just the
		// record list, and without enumerating (or provisioning) the
		// phantom items.
		expectInvalid(l.name+": max uint32 count on small body", "implausible list count",
			func(p []byte) []byte {
				binary.BigEndian.PutUint32(p[l.site.countAt:], 0xffffffff)
				return p
			})

		// C) Every early item is whole; the final item is missing its last
		// required field by one byte. Enough bytes remain to pass the coarse
		// per-item count floor, so this failure must surface while reading
		// that item — proving the item-level truncation guard, not only the
		// count bound, is in place.
		lastItemEnd := l.site.itemEnds[len(l.site.itemEnds)-1]
		expectInvalid(l.name+": later item missing required field", "truncated archive payload",
			func(p []byte) []byte { return p[:lastItemEnd-1] })
	}

	// B) A count word physically cut off mid-read. For the three inner
	// lists this needs a one-record payload: the outer record-count floor
	// (22 bytes per record) must still pass so the reader actually reaches
	// the inner list and proves its own u32 truncation guard.
	inner := buildInnerListCountTruncationPayloads(t)
	cutCountWord := func(name string, full []byte, countAt int) {
		t.Helper()
		// These are single-record payloads, so the outer record-count floor
		// (22 bytes/record) still passes at this cut; the reader must reach
		// the inner list and prove its own count-word truncation guard.
		cut := countAt + 2
		data := framePayload(full[:cut])
		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidArchive) || got != nil {
			t.Fatalf("%s: records=%v err=%v, want ErrInvalidArchive, nil", name, got, err)
		}
		if !strings.Contains(err.Error(), "truncated archive payload") {
			t.Fatalf("%s: err = %q, want a mid-read count truncation", name, err)
		}
	}
	cutCountWord("policies count word", inner.policiesPayload, inner.policiesCountAt)
	cutCountWord("roles count word", inner.rolesPayload, inner.rolesCountAt)
	cutCountWord("matched count word", inner.matchedPayload, inner.matchedCountAt)

	// B for the outer record list: header complete, its count word cut.
	headerOnly := buildArchiveHeader(t)
	recordCountCut := append(append([]byte(nil), headerOnly...), 0x00, 0x00)
	if got, err := DecodeAuditArchive(framePayload(recordCountCut), "acme", cp); !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("records count word: records=%v err=%v, want ErrInvalidArchive, nil", got, err)
	}

	// A dedicated emphasis for the requirement: a tiny archive declaring
	// 4294967295 records must return the deterministic error promptly,
	// without crashing or provisioning as if the count were real.
	w := &archiveWriter{}
	w.stringField("acme")
	w.u32(0)
	w.stringField("g")
	w.u32(0xffffffff)
	if w.err != nil {
		t.Fatal(w.err)
	}
	tinyHuge := framePayload(w.buf)

	var before, after runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&before)
	got, err := DecodeAuditArchive(tinyHuge, "acme", cp)
	runtime.ReadMemStats(&after)
	if !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("tiny archive with max count: records=%v err=%v, want ErrInvalidArchive, nil", got, err)
	}
	if !strings.Contains(err.Error(), "implausible list count") {
		t.Fatalf("tiny archive with max count: err = %q, want count-bound rejection", err)
	}
	// A regression that trusted the count would try to provision billions
	// of records; bound what this error path may allocate.
	if alloc := after.TotalAlloc - before.TotalAlloc; alloc > 16<<20 {
		t.Fatalf("max-count decode allocated %d bytes, want a small error path", alloc)
	}
}

// innerListTruncation holds one complete one-record payload and the offset
// of a targeted inner list's count word.
type innerListTruncation struct {
	policiesPayload              []byte
	policiesCountAt              int
	rolesPayload, matchedPayload []byte
	rolesCountAt                 int
	matchedCountAt               int
}

// buildInnerListCountTruncationPayloads hand-builds structurally complete
// one-record payloads (fingerprints are irrelevant here because a truncated
// count fails format decoding before any content check) and reports the
// offset of each inner list's count word.
func buildInnerListCountTruncationPayloads(t *testing.T) innerListTruncation {
	t.Helper()
	var out innerListTruncation

	// One policy-change record whose policy list carries two policies.
	{
		w := &archiveWriter{}
		w.stringField("acme")
		w.u32(1)
		w.stringField("g")
		w.u32(1) // one record
		w.stringField("acme")
		w.u32(1)
		w.stringField(AuditPolicyChange)
		w.raw([]byte{archiveTagPresent}) // change present
		w.u32(1)                         // change version
		w.raw([]byte{archiveTagPresent}) // policy list present
		out.policiesCountAt = len(w.buf)
		w.u32(2)
		w.policy(allowPolicy("p1", "u1", "read", "org/a", false))
		w.policy(allowPolicy("p2", "u1", "read", "org/a", false))
		w.u32(0)           // source version
		w.boolean(false)   // rolled back
		w.raw(nilMarker()) // decision absent
		w.stringField("p") // prev fingerprint
		w.stringField("f") // own fingerprint
		if w.err != nil {
			t.Fatal(w.err)
		}
		out.policiesPayload = w.buf
	}

	// One decision record whose subject roles and decision matched list
	// each carry two strings.
	{
		w := &archiveWriter{}
		w.stringField("acme")
		w.u32(1)
		w.stringField("g")
		w.u32(1) // one record
		w.stringField("acme")
		w.u32(1)
		w.stringField(AuditDecision)
		w.raw([]byte{archiveTagNil})     // change absent
		w.raw([]byte{archiveTagPresent}) // decision present
		w.stringField("acme")            // SubjectOrg
		w.stringField("acme")            // ResourceOrg
		w.stringField("u1")              // subject ID
		w.stringField("user")            // subject kind
		w.raw([]byte{archiveTagPresent}) // roles present
		out.rolesCountAt = len(w.buf)
		w.u32(2)
		w.stringField("role-a")
		w.stringField("role-b")
		w.boolean(false) // subject disabled
		w.stringField("r1")
		w.stringField("org/a")
		w.stringField("read") // action
		w.boolean(true)       // decision allowed
		w.stringField("matched allow policy")
		w.raw([]byte{archiveTagPresent}) // matched present
		out.matchedCountAt = len(w.buf)
		w.u32(2)
		w.stringField("p1")
		w.stringField("p2")
		w.u32(1)           // decision version
		w.stringField("p") // prev fingerprint
		w.stringField("f") // own fingerprint
		if w.err != nil {
			t.Fatal(w.err)
		}
		out.rolesPayload = w.buf
		out.matchedPayload = w.buf
	}
	return out
}

// nilMarker returns the one-byte absent/nil marker as a slice.
func nilMarker() []byte { return []byte{archiveTagNil} }

// buildArchiveHeader writes just the payload header (embedded org, end
// sequence and checkpoint fingerprint) that precedes the record count.
func buildArchiveHeader(t *testing.T) []byte {
	t.Helper()
	w := &archiveWriter{}
	w.stringField("acme")
	w.u32(0)
	w.stringField("g")
	if w.err != nil {
		t.Fatal(w.err)
	}
	return w.buf
}

// TestArchiveLaterRecordListDamageDiscardsPrefix is the record-level case
// the requirement names: a complete policy change and a complete decision
// have already been read when a *later* record's inner list turns out to
// promise items its bytes cannot provide. The whole read must fail and the
// intact prefix must never be handed to the caller.
func TestArchiveLaterRecordListDamageDiscardsPrefix(t *testing.T) {
	thirdReason := "third-decision-reason-7f3a"
	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version: 1, Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1"}, Version: 1},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditDecision, nil, &DecisionRecord{
				Request:  request("acme", "u1", "r1", "org/a", "read"),
				Decision: Decision{Allowed: false, Reason: thirdReason, Matched: []string{"p1"}, Version: 1},
			}
		},
	})
	good, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode: %v", err)
	}

	// The third record's matched list follows its unique reason string:
	// reason stringField bytes, then one list marker, then its count word.
	damaged := reframe(t, good, func(payload []byte) []byte {
		idx := bytes.Index(payload, []byte(thirdReason))
		if idx < 0 {
			t.Fatal("third-record reason not found")
		}
		if bytes.Index(payload[idx+1:], []byte(thirdReason)) >= 0 {
			t.Fatal("third-record reason must be unique for an unambiguous locate")
		}
		countAt := idx + len(thirdReason) + 1 // skip reason bytes and the list marker
		binary.BigEndian.PutUint32(payload[countAt:], 0xffffffff)
		return payload
	})

	got, err := DecodeAuditArchive(damaged, "acme", cp)
	if !errors.Is(err, ErrInvalidArchive) || got != nil {
		t.Fatalf("later-record list damage: records=%v err=%v, want ErrInvalidArchive, nil", got, err)
	}
}

// TestArchiveListContentChangeIsNotArchiveDamage keeps format damage
// separate from untrusted content: a single in-list byte flipped with the
// checksum recomputed is fully readable as a format (every length and
// marker intact), so it must fail as content with ErrInvalidRange — not be
// swept into ErrInvalidArchive merely because the byte lives inside a
// policy or string list.
func TestArchiveListContentChangeIsNotArchiveDamage(t *testing.T) {
	good, _, cp := listCorruptionFixture(t)
	payload := payloadOf(t, good)
	sites := inspectTwoRecordPayload(t, payload)

	flipOneListByte := func(name string, site listSite) {
		t.Helper()
		// Flip a byte in the second item's content (past its length word),
		// leaving every length prefix and marker untouched.
		secondItem := site.itemEnds[0]
		tampered := append([]byte(nil), payload...)
		tampered[secondItem+4] ^= 0x01
		data := framePayload(tampered)
		got, err := DecodeAuditArchive(data, "acme", cp)
		if !errors.Is(err, ErrInvalidRange) || got != nil {
			t.Fatalf("%s: records=%v err=%v, want ErrInvalidRange, nil", name, got, err)
		}
		if errors.Is(err, ErrInvalidArchive) {
			t.Fatalf("%s: readable-format content change reported as archive damage", name)
		}
	}
	flipOneListByte("matched list byte", sites.matched)
	flipOneListByte("roles list byte", sites.roles)
	flipOneListByte("policy list byte", sites.policies)
}

// TestArchiveValidListShapesRoundTrip locks the legal boundaries the
// corruption guard must not disturb: nil and non-nil empty policy/string
// lists keep their exact shape, populated lists keep order and raw bytes,
// and neither fingerprints nor the caller checkpoint change. The decoded
// material still verifies and feeds offline review unchanged.
func TestArchiveValidListShapesRoundTrip(t *testing.T) {
	req := request("acme", "u1", "r1", "org/a", "read")
	recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
		// Policy list shapes.
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 1, Policies: nil}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{
				Version: 2, SourceVersion: 1, RolledBack: true, Policies: []Policy{},
			}, nil
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			return AuditPolicyChange, &PolicyChange{Version: 3, Policies: []Policy{
				// Raw, non-UTF-8 bytes and a fixed order must be preserved.
				{ID: "p" + invalidByte, Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: "r" + anotherInvalidByte},
				allowPolicy("p2", "u1", "read", "org/a", false),
			}}, nil
		},
		// String list shapes across subject roles and matched policies.
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = nil
			return AuditDecision, nil, &DecisionRecord{
				Request:  r,
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: nil, Version: 3},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = []string{}
			return AuditDecision, nil, &DecisionRecord{
				Request:  r,
				Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{}, Version: 3},
			}
		},
		func(seq int) (string, *PolicyChange, *DecisionRecord) {
			r := req
			r.Subject.Roles = []string{"zeta", "alpha"} // order is preserved, not sorted
			return AuditDecision, nil, &DecisionRecord{
				Request: r,
				Decision: Decision{Allowed: true, Reason: "matched allow policy",
					Matched: []string{"p" + invalidByte, "p2"}, Version: 3},
			}
		},
	})

	archive, err := EncodeAuditArchive("acme", recs, cp)
	if err != nil {
		t.Fatalf("encode list shapes: %v", err)
	}
	got, err := DecodeAuditArchive(archive, "acme", cp)
	if err != nil {
		t.Fatalf("decode list shapes: %v", err)
	}
	if !reflect.DeepEqual(got, recs) {
		t.Fatalf("valid list shapes changed across the archive:\n got %+v\nwant %+v", got, recs)
	}

	// Explicit nil-vs-empty preservation for both list kinds.
	if got[0].Change.Policies != nil {
		t.Fatal("nil policy list decoded non-nil")
	}
	if got[1].Change.Policies == nil || len(got[1].Change.Policies) != 0 {
		t.Fatal("empty non-nil policy list lost its shape")
	}
	if got[3].Decision.Request.Subject.Roles != nil || got[3].Decision.Decision.Matched != nil {
		t.Fatal("nil string lists decoded non-nil")
	}
	if got[4].Decision.Request.Subject.Roles == nil || got[4].Decision.Decision.Matched == nil {
		t.Fatal("empty non-nil string lists decoded as nil")
	}
	// Populated lists: exact order and raw bytes, including non-UTF-8.
	wantRoles := []string{"zeta", "alpha"}
	if !reflect.DeepEqual(got[5].Decision.Request.Subject.Roles, wantRoles) {
		t.Fatalf("roles order/bytes changed: got %q want %q", got[5].Decision.Request.Subject.Roles, wantRoles)
	}
	wantMatched := []string{"p" + invalidByte, "p2"}
	if !reflect.DeepEqual(got[5].Decision.Decision.Matched, wantMatched) {
		t.Fatalf("matched order/bytes changed: got %q want %q", got[5].Decision.Decision.Matched, wantMatched)
	}
	policies := got[2].Change.Policies
	if policies[0].ID != "p"+invalidByte || policies[0].ResourceID != "r"+anotherInvalidByte {
		t.Fatalf("policy raw bytes changed: id=%q resource=%q", policies[0].ID, policies[0].ResourceID)
	}

	// Fingerprints and the retained checkpoint are untouched, and the
	// material remains directly usable by offline verification.
	for i := range got {
		if got[i].Fingerprint != recs[i].Fingerprint {
			t.Fatalf("record %d fingerprint changed", i+1)
		}
	}
	if err := VerifyAudit("acme", got, cp); err != nil {
		t.Fatalf("decoded valid-list material must verify: %v", err)
	}
}

