1	// This file pins down the decoder's handling of corrupted *single-byte
2	// markers*: archives whose outer framing, declared payload length and
3	// checksum are all correct, but where one marker byte inside the payload
4	// carries a value the format does not define. The format uses one-byte
5	// markers for booleans (policy Recursive, change RolledBack, subject
6	// Disabled, decision Allowed), for payload presence (the change and
7	// decision payloads) and for list presence (the policy list, the subject
8	// roles and the matched policy list). Only 0 and 1 are legal at every one
9	// of these positions.
10	//
11	// Two failure classes must stay distinguishable. A marker byte of 2, 0xff
12	// or any other undefined value makes the archive uninterpretable: no
13	// non-zero byte may be read as "true" or "present", so the whole read fails
14	// with ErrInvalidArchive and delivers no records — even though the
15	// recomputed outer checksum still matches, proving the rejection comes
16	// from the internal format check. Flipping a boolean between its two legal
17	// values instead keeps the structure readable but changes the audited
18	// content: against the original fingerprints and the caller's retained
19	// checkpoint that is an audit-chain failure, ErrInvalidRange, never a
20	// format error and never a deliverable record.
21	package darksafe
22	
23	import (
24		"bytes"
25		"errors"
26		"fmt"
27		"reflect"
28		"strings"
29		"testing"
30	)
31	
32	// markerEvent is one single-byte marker located in the fixture payload:
33	// its human label, its payload offset and the legal value the fixture
34	// carries there.
35	type markerEvent struct {
36		name  string
37		at    int
38		value byte
39	}
40	
41	// markerFixture builds complete, valid material exercising every marker
42	// kind in both of its legal states: a publish whose two policies carry
43	// Recursive true and false, an allowed decision with populated roles and
44	// matched lists, a publish with a non-nil empty policy set, one with a nil
45	// policy set, a rollback (RolledBack true) and a disabled-subject decision
46	// with nil roles and nil matched list. The chain is semantically
47	// consistent, so the decoded control material still passes offline review.
48	func markerFixture(t *testing.T) ([]byte, []AuditRecord, Checkpoint) {
49		t.Helper()
50		p1 := Policy{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, Recursive: true}
51		p2 := Policy{ID: "p2", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: "r1"}
52		enabledReq := request("acme", "u1", "r1", "org/a", "read")
53		enabledReq.Subject.Roles = []string{"role-a", "role-b"}
54		disabledReq := request("acme", "u1", "r1", "org/a", "read")
55		disabledReq.Subject.Disabled = true
56	
57		recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
58			func(seq int) (string, *PolicyChange, *DecisionRecord) {
59				return AuditPolicyChange, &PolicyChange{Version: 1, Policies: []Policy{p1, p2}}, nil
60			},
61			func(seq int) (string, *PolicyChange, *DecisionRecord) {
62				return AuditDecision, nil, &DecisionRecord{
63					Request:  enabledReq,
64					Decision: Decision{Allowed: true, Reason: "matched allow policy", Matched: []string{"p1", "p2"}, Version: 1},
65				}
66			},
67			func(seq int) (string, *PolicyChange, *DecisionRecord) {
68				return AuditPolicyChange, &PolicyChange{Version: 2, Policies: []Policy{}}, nil
69			},
70			func(seq int) (string, *PolicyChange, *DecisionRecord) {
71				return AuditPolicyChange, &PolicyChange{Version: 3, Policies: nil}, nil
72			},
73			func(seq int) (string, *PolicyChange, *DecisionRecord) {
74				return AuditPolicyChange, &PolicyChange{Version: 4, SourceVersion: 1, RolledBack: true, Policies: []Policy{p1, p2}}, nil
75			},
76			func(seq int) (string, *PolicyChange, *DecisionRecord) {
77				return AuditDecision, nil, &DecisionRecord{
78					Request:  disabledReq,
79					Decision: Decision{Allowed: false, Reason: "subject is disabled", Version: 0},
80				}
81			},
82		})
83		archive, err := EncodeAuditArchive("acme", recs, cp)
84		if err != nil {
85			t.Fatalf("encode marker fixture: %v", err)
86		}
87		return archive, recs, cp
88	}
89	
90	// walkMarkerPayload mirrors archiveReader over the marker fixture payload,
91	// recording every single-byte marker (booleans, payload presence, list
92	// presence) with its offset. It exists only to locate the bytes the tests
93	// corrupt; it follows the markers it reads, so a format change desyncs the
94	// walk and fails the fixture-layout expectation loudly rather than letting
95	// a test corrupt the wrong field.
96	func walkMarkerPayload(t *testing.T, p []byte) []markerEvent {
97		t.Helper()
98		c := &payloadInspector{b: p}
99		var events []markerEvent
100		mark := func(name string) {
101			// Read the offset before consuming the byte: evaluation order of the
102			// two reads matters and must not be left to a composite literal.
103			at := c.pos
104			events = append(events, markerEvent{name: name, at: at, value: c.marker()})
105		}
106		last := func() byte { return events[len(events)-1].value }
107		stringList := func(name string) {
108			mark(name)
109			if last() == archiveTagNil {
110				return
111			}
112			n := c.u32()
113			for i := 0; i < n; i++ {
114				c.str()
115			}
116		}
117		policyList := func(name string, rec int) {
118			mark(name)
119			if last() == archiveTagNil {
120				return
121			}
122			n := c.u32()
123			for i := 0; i < n; i++ {
124				c.str() // ID
125				c.str() // Subject
126				c.str() // Action
127				c.str() // Scope
128				c.str() // Effect
129				mark(fmt.Sprintf("record %d policy %d recursive", rec, i))
130				c.str() // ResourceID
131			}
132		}
133	
134		c.str()    // embedded org
135		c.pos += 4 // embedded end sequence
136		c.str()    // embedded checkpoint fingerprint
137		n := c.u32()
138		for rec := 1; rec <= n; rec++ {
139			c.str()    // org
140			c.pos += 4 // seq
141			c.str()    // kind
142			mark(fmt.Sprintf("record %d change payload", rec))
143			if last() == archiveTagPresent {
144				c.pos += 4 // change version
145				policyList(fmt.Sprintf("record %d policy list", rec), rec)
146				c.pos += 4 // source version
147				mark(fmt.Sprintf("record %d rolled back", rec))
148			}
149			mark(fmt.Sprintf("record %d decision payload", rec))
150			if last() == archiveTagPresent {
151				c.str() // request SubjectOrg
152				c.str() // request ResourceOrg
153				c.str() // subject ID
154				c.str() // subject kind
155				stringList(fmt.Sprintf("record %d subject roles", rec))
156				mark(fmt.Sprintf("record %d subject disabled", rec))
157				c.str() // resource ID
158				c.str() // resource scope
159				c.str() // action
160				mark(fmt.Sprintf("record %d decision allowed", rec))
161				c.str() // decision reason
162				stringList(fmt.Sprintf("record %d matched policies", rec))
163				c.pos += 4 // decision version
164			}
165			c.str() // prev fingerprint
166			c.str() // own fingerprint
167		}
168		if c.pos != len(p) {
169			t.Fatalf("marker walk ended at %d, payload length %d", c.pos, len(p))
170		}
171		return events
172	}
173	
174	// markerOffset returns the payload offset of one named marker site.
175	func markerOffset(t *testing.T, events []markerEvent, name string) int {
176		t.Helper()
177		for _, ev := range events {
178			if ev.name == name {
179				return ev.at
180			}
181		}
182		t.Fatalf("marker site %q not walked", name)
183		return 0
184	}
185	
186	// expectMarkerFailure reframes one mutated payload with a consistent outer
187	// length and checksum, then asserts the read fails with the wanted error
188	// class (and not the other one), delivers no records, and rewrites neither
189	// the archive bytes nor the retained checkpoint handed to it.
190	func expectMarkerFailure(t *testing.T, name string, payload []byte, cp Checkpoint, want, notWant error, wantSubstr string) {
191		t.Helper()
192		data := framePayload(payload)
193		dataSnapshot := append([]byte(nil), data...)
194		cpSnapshot := cp
195	
196		got, err := DecodeAuditArchive(data, "acme", cp)
197		if !errors.Is(err, want) {
198			t.Fatalf("%s: err = %v, want %v", name, err, want)
199		}
200		if errors.Is(err, notWant) {
201			t.Fatalf("%s: err = %v must not be %v", name, err, notWant)
202		}
203		if got != nil {
204			t.Fatalf("%s: returned %d records on a damaged marker, want nil", name, len(got))
205		}
206		if wantSubstr != "" && !strings.Contains(err.Error(), wantSubstr) {
207			t.Fatalf("%s: err = %q, want substring %q", name, err.Error(), wantSubstr)
208		}
209		if !bytes.Equal(data, dataSnapshot) {
210			t.Fatalf("%s: failed decode rewrote the archive bytes", name)
211		}
212		if cp != cpSnapshot {
213			t.Fatalf("%s: failed decode rewrote the retained checkpoint", name)
214		}
215	}
216	
217	// TestArchiveMarkerFixtureLayout locks the fixture's marker map: every
218	// marker kind appears, in both legal states, exactly where the walker
219	// expects it. A format or fixture change breaks this test instead of
220	// silently moving the corruption targets of the other tests in this file.
221	func TestArchiveMarkerFixtureLayout(t *testing.T) {
222		archive, _, _ := markerFixture(t)
223		events := walkMarkerPayload(t, payloadOf(t, archive))
224	
225		want := []struct {
226			name  string
227			value byte
228		}{
229			{"record 1 change payload", archiveTagPresent},
230			{"record 1 policy list", archiveTagPresent},
231			{"record 1 policy 0 recursive", archiveTagBoolTrue},
232			{"record 1 policy 1 recursive", archiveTagBoolFalse},
233			{"record 1 rolled back", archiveTagBoolFalse},
234			{"record 1 decision payload", archiveTagNil},
235			{"record 2 change payload", archiveTagNil},
236			{"record 2 decision payload", archiveTagPresent},
237			{"record 2 subject roles", archiveTagPresent},
238			{"record 2 subject disabled", archiveTagBoolFalse},
239			{"record 2 decision allowed", archiveTagBoolTrue},
240			{"record 2 matched policies", archiveTagPresent},
241			{"record 3 change payload", archiveTagPresent},
242			{"record 3 policy list", archiveTagPresent}, // non-nil empty set
243			{"record 3 rolled back", archiveTagBoolFalse},
244			{"record 3 decision payload", archiveTagNil},
245			{"record 4 change payload", archiveTagPresent},
246			{"record 4 policy list", archiveTagNil},
247			{"record 4 rolled back", archiveTagBoolFalse},
248			{"record 4 decision payload", archiveTagNil},
249			{"record 5 change payload", archiveTagPresent},
250			{"record 5 policy list", archiveTagPresent},
251			{"record 5 policy 0 recursive", archiveTagBoolTrue},
252			{"record 5 policy 1 recursive", archiveTagBoolFalse},
253			{"record 5 rolled back", archiveTagBoolTrue},
254			{"record 5 decision payload", archiveTagNil},
255			{"record 6 change payload", archiveTagNil},
256			{"record 6 decision payload", archiveTagPresent},
257			{"record 6 subject roles", archiveTagNil},
258			{"record 6 subject disabled", archiveTagBoolTrue},
259			{"record 6 decision allowed", archiveTagBoolFalse},
260			{"record 6 matched policies", archiveTagNil},
261		}
262		if len(events) != len(want) {
263			t.Fatalf("walked %d marker sites, want %d: %+v", len(events), len(want), events)
264		}
265		for i, w := range want {
266			if events[i].name != w.name || events[i].value != w.value {
267				t.Fatalf("marker %d = %+v, want %s with value %d", i, events[i], w.name, w.value)
268			}
269		}
270	}
271	
272	// TestArchiveInvalidMarkerBytesRejected corrupts every single-byte marker
273	// in turn to a value the format does not define (2 and 0xff). The outer
274	// length and checksum are recomputed, so they still validate: the
275	// rejection must come from the internal marker check, surface as
276	// ErrInvalidArchive (matched by errors.Is, and never as the content error
277	// ErrInvalidRange), and deliver no records — an arbitrary non-zero byte is
278	// not "true" and not "present".
279	func TestArchiveInvalidMarkerBytesRejected(t *testing.T) {
280		archive, _, cp := markerFixture(t)
281		basePayload := payloadOf(t, archive)
282		events := walkMarkerPayload(t, basePayload)
283	
284		for _, ev := range events {
285			for _, bad := range []byte{2, 0xff} {
286				payload := append([]byte(nil), basePayload...)
287				payload[ev.at] = bad
288				expectMarkerFailure(t, fmt.Sprintf("%s -> %d", ev.name, bad),
289					payload, cp, ErrInvalidArchive, ErrInvalidRange, "marker")
290			}
291		}
292	}
293	
294	// TestArchiveBooleanFlipChangesContentNotFormat flips every boolean marker
295	// between its two legal values. The archive stays structurally readable —
296	// every marker, length and count is intact — but the audited content no
297	// longer matches the original fingerprints, so against the caller's
298	// retained checkpoint the read must fail as ErrInvalidRange, never be
299	// reported as archive-format damage, and deliver no records.
300	func TestArchiveBooleanFlipChangesContentNotFormat(t *testing.T) {
301		archive, _, cp := markerFixture(t)
302		basePayload := payloadOf(t, archive)
303		events := walkMarkerPayload(t, basePayload)
304	
305		isBool := func(name string) bool {
306			return strings.Contains(name, "recursive") ||
307				strings.Contains(name, "rolled back") ||
308				strings.Contains(name, "disabled") ||
309				strings.Contains(name, "allowed")
310		}
311		flipped := 0
312		for _, ev := range events {
313			if !isBool(ev.name) {
314				continue
315			}
316			flipped++
317			payload := append([]byte(nil), basePayload...)
318			payload[ev.at] = ev.value ^ 1 // 0 becomes 1, 1 becomes 0: still a legal marker
319			expectMarkerFailure(t, ev.name+" flipped", payload, cp, ErrInvalidRange, ErrInvalidArchive, "")
320		}
321		if flipped != 12 {
322			t.Fatalf("flipped %d boolean sites, want the 12 the fixture carries", flipped)
323		}
324	}
325	
326	// TestArchiveLaterRecordMarkerDamageDiscardsPrefix is the all-or-nothing
327	// boundary: every record but the last decodes cleanly, yet one illegal
328	// marker in the final record fails the whole read. The intact prefix is
329	// proved readable on its own, so a nil result for the full archive can
330	// only mean the prefix was deliberately withheld.
331	func TestArchiveLaterRecordMarkerDamageDiscardsPrefix(t *testing.T) {
332		archive, recs, cp := markerFixture(t)
333		basePayload := payloadOf(t, archive)
334		events := walkMarkerPayload(t, basePayload)
335	
336		// The first five records, archived with their own checkpoint, read and
337		// review fine: the prefix really is intact.
338		prefixCP := Checkpoint{Org: "acme", EndSeq: 5, Fingerprint: recs[4].Fingerprint}
339		prefixArchive, err := EncodeAuditArchive("acme", recs[:5], prefixCP)
340		if err != nil {
341			t.Fatalf("encode prefix: %v", err)
342		}
343		prefix, err := DecodeAuditArchive(prefixArchive, "acme", prefixCP)
344		if err != nil || len(prefix) != 5 {
345			t.Fatalf("intact prefix must decode: %d records, %v", len(prefix), err)
346		}
347		if review, err := RecheckDecisionOffline("acme", prefix, prefixCP, 2); err != nil || !review.Consistent {
348			t.Fatalf("intact prefix must review: %+v, %v", review, err)
349		}
350	
351		// An illegal boolean marker and an illegal list marker in the last
352		// record each sink the entire read; no record prefix comes back.
353		for _, site := range []string{"record 6 decision allowed", "record 6 matched policies", "record 6 change payload"} {
354			payload := append([]byte(nil), basePayload...)
355			payload[markerOffset(t, events, site)] = 0xff
356			expectMarkerFailure(t, site, payload, cp, ErrInvalidArchive, ErrInvalidRange, "marker")
357		}
358	}
359	
360	// TestArchiveUndamagedMarkersRoundTrip is the control: the same fixture
361	// with no byte touched decodes cleanly, keeps every boolean's exact value
362	// and the nil versus non-nil-empty versus populated distinction of every
363	// list, and still feeds the existing offline decision review.
364	func TestArchiveUndamagedMarkersRoundTrip(t *testing.T) {
365		archive, recs, cp := markerFixture(t)
366		got, err := DecodeAuditArchive(archive, "acme", cp)
367		if err != nil {
368			t.Fatalf("decode control: %v", err)
369		}
370		if !reflect.DeepEqual(got, recs) {
371			t.Fatalf("control round trip changed the records:\n got %+v\nwant %+v", got, recs)
372		}
373	
374		// Booleans keep their exact values in both states.
375		if !got[0].Change.Policies[0].Recursive || got[0].Change.Policies[1].Recursive {
376			t.Fatal("policy Recursive booleans changed across the archive")
377		}
378		if got[0].Change.RolledBack || !got[4].Change.RolledBack {
379			t.Fatal("RolledBack booleans changed across the archive")
380		}
381		if got[1].Decision.Request.Subject.Disabled || !got[5].Decision.Request.Subject.Disabled {
382			t.Fatal("subject Disabled booleans changed across the archive")
383		}
384		if !got[1].Decision.Decision.Allowed || got[5].Decision.Decision.Allowed {
385			t.Fatal("decision Allowed booleans changed across the archive")
386		}
387	
388		// Nil, non-nil empty and populated lists keep their distinct shapes.
389		if got[2].Change.Policies == nil || len(got[2].Change.Policies) != 0 {
390			t.Fatal("non-nil empty policy set lost its shape")
391		}
392		if got[3].Change.Policies != nil {
393			t.Fatal("nil policy set decoded as non-nil")
394		}
395		if got[5].Decision.Request.Subject.Roles != nil || got[5].Decision.Decision.Matched != nil {
396			t.Fatal("nil roles/matched lists decoded as non-nil")
397		}
398		if want := []string{"role-a", "role-b"}; !reflect.DeepEqual(got[1].Decision.Request.Subject.Roles, want) {
399			t.Fatalf("roles = %q, want %q", got[1].Decision.Request.Subject.Roles, want)
400		}
401		if want := []string{"p1", "p2"}; !reflect.DeepEqual(got[1].Decision.Decision.Matched, want) {
402			t.Fatalf("matched = %q, want %q", got[1].Decision.Decision.Matched, want)
403		}
404	
405		// The decoded material still serves the existing offline review, for
406		// the allowed decision and for the disabled-subject denial alike.
407		allowReview, err := RecheckDecisionOffline("acme", got, cp, 2)
408		if err != nil || !allowReview.Consistent || !allowReview.Recomputed.Allowed {
409			t.Fatalf("control allow review = %+v, %v", allowReview, err)
410		}
411		denyReview, err := RecheckDecisionOffline("acme", got, cp, 6)
412		if err != nil || !denyReview.Consistent || denyReview.Recomputed.Allowed {
413			t.Fatalf("control disabled-subject review = %+v, %v", denyReview, err)
414		}
415	}
