		}
	}
	req := request("acme", "u1", "r1", "org/a", "read")
	req.Subject.Disabled = true
	if d := s.Decide("acme", req); d.Allowed || d.Reason != "subject is disabled" {
		t.Fatalf("disabled subject: %+v", d)
	}
