	if err != nil || v3 != 3 {
		t.Fatalf("rollback = %d, %v; want 3, nil", v3, err)
	}
	d := s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
	if !d.Allowed || d.Version != 3 {
		t.Fatalf("after rollback: %+v, want allowed with version 3", d)
	}
